package com.slayertaskluck;

import lombok.AllArgsConstructor;

@AllArgsConstructor
public enum OverlayMode
{
	WHILE_SKIPPING("While skipping"),
	ALWAYS("Always"),
	NEVER("Never");

	private final String label;

	@Override
	public String toString()
	{
		return label;
	}
}

package com.slayertaskluck;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(SlayerTaskLuckConfig.GROUP)
public interface SlayerTaskLuckConfig extends Config
{
	String GROUP = "slayertaskluck";

	@ConfigSection(
		name = "Overlay",
		description = "The small on-screen summary. The side panel is always available.",
		position = 0
	)
	String overlaySection = "overlay";

	@ConfigSection(
		name = "Masters",
		description = "Which masters count as fillers. Filler tasks are skips: they're logged and counted as detours, never as luck rolls.",
		position = 1
	)
	String mastersSection = "masters";

	@ConfigSection(
		name = "Luck thresholds",
		description = "When a result is called unlucky or lucky",
		position = 2,
		closedByDefault = true
	)
	String thresholdSection = "thresholds";

	@ConfigItem(
		keyName = "overlayMode",
		name = "Show overlay",
		description = "While skipping: when you have no task, a filler task, or are talking to a master.",
		position = 0,
		section = overlaySection
	)
	default OverlayMode overlayMode()
	{
		return OverlayMode.WHILE_SKIPPING;
	}

	@ConfigItem(
		keyName = "showWantedLine",
		name = "Show wanted line",
		description = "Wanted tasks received vs expected",
		position = 1,
		section = overlaySection
	)
	default boolean showWantedLine()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showDetoursLine",
		name = "Show detours line",
		description = "Filler tasks done since your last wanted task, and the time they took",
		position = 2,
		section = overlaySection
	)
	default boolean showDetoursLine()
	{
		return false;
	}

	@ConfigItem(
		keyName = "fillerAya",
		name = "Aya is a filler",
		description = "Count Aya's tasks as skips",
		position = 0,
		section = mastersSection
	)
	default boolean fillerAya()
	{
		return true;
	}

	@ConfigItem(
		keyName = "fillerTurael",
		name = "Turael is a filler",
		description = "Count Turael's tasks as skips",
		position = 1,
		section = mastersSection
	)
	default boolean fillerTurael()
	{
		return true;
	}

	@ConfigItem(
		keyName = "fillerSpria",
		name = "Spria is a filler",
		description = "Count Spria's tasks as skips",
		position = 2,
		section = mastersSection
	)
	default boolean fillerSpria()
	{
		return true;
	}

	@Range(min = 1, max = 25)
	@ConfigItem(
		keyName = "unluckyPercent",
		name = "Unlucky below (%)",
		description = "Results rarer than this on the unlucky side are shown in red",
		position = 0,
		section = thresholdSection
	)
	default int unluckyPercent()
	{
		return 10;
	}

	@Range(min = 1, max = 25)
	@ConfigItem(
		keyName = "luckyPercent",
		name = "Lucky above (%)",
		description = "Results rarer than this on the lucky side are shown in green",
		position = 1,
		section = thresholdSection
	)
	default int luckyPercent()
	{
		return 10;
	}
}

package com.slayertaskluck;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.slayertaskluck.math.FairnessCache;
import com.slayertaskluck.tracking.CsvExport;
import com.slayertaskluck.tracking.Masters;
import com.slayertaskluck.tracking.SlayerTracker;
import com.slayertaskluck.tracking.TrackerStore;
import com.slayertaskluck.ui.PanelActions;
import com.slayertaskluck.ui.TrackerView;
import com.slayertaskluck.ui.SlayerTaskLuckOverlay;
import com.slayertaskluck.ui.SlayerTaskLuckPanel;
import com.slayertaskluck.ui.ViewBuilder;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Slayer Task Luck",
	// Never change: names the data folder returned by getPluginDirectory().
	internalName = "slayer-task-luck",
	description = "Logs your Slayer task rolls with their exact odds and shows how lucky you have been at getting the tasks you want",
	tags = {"slayer", "task", "luck", "odds", "statistics", "turael", "aya", "skip"}
)
public class SlayerTaskLuckPlugin extends Plugin
{
	private static final long RECOMPUTE_DELAY_MS = 150;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private SlayerTaskLuckConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private Gson gson;

	private ScheduledExecutorService executor;
	private TrackerStore store;
	private volatile SlayerTracker tracker;
	private SlayerTaskLuckPanel panel;
	private NavigationButton navButton;
	private SlayerTaskLuckOverlay overlay;
	private volatile TrackerView view = TrackerView.EMPTY;
	private final AtomicBoolean recomputeQueued = new AtomicBoolean();
	/** Only touched on the executor thread. */
	private FairnessCache fairnessCache;

	@Override
	protected void startUp() throws Exception
	{
		executor = Executors.newSingleThreadScheduledExecutor(r ->
		{
			final Thread t = new Thread(r, "slayer-task-luck");
			t.setDaemon(true);
			return t;
		});
		fairnessCache = new FairnessCache();
		store = new TrackerStore(gson, executor, this::getPluginDirectory, this::scheduleRecompute);
		tracker = new SlayerTracker(client, store, config, this::scheduleRecompute);

		panel = new SlayerTaskLuckPanel(new Actions());
		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Slayer Task Luck")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		overlay = new SlayerTaskLuckOverlay(config, () -> view, tracker::isSkippingContext);
		overlayManager.add(overlay);

		eventBus.register(tracker);
		clientThread.invoke(() ->
		{
			tracker.start();
			store.switchProfile(configManager.getRSProfileKey());
		});
		scheduleRecompute();
	}

	@Override
	protected void shutDown() throws Exception
	{
		eventBus.unregister(tracker);
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		store.flush();
		// Non-blocking: lets the final save finish in the background, then the thread ends.
		executor.shutdown();
		navButton = null;
		panel = null;
		overlay = null;
		tracker = null;
		view = TrackerView.EMPTY;
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		store.switchProfile(configManager.getRSProfileKey());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SlayerTaskLuckConfig.GROUP.equals(event.getGroup()))
		{
			scheduleRecompute();
		}
	}

	/** Coalesces changes into one background recompute of the view. Safe from any thread. */
	private void scheduleRecompute()
	{
		if (recomputeQueued.compareAndSet(false, true))
		{
			try
			{
				executor.schedule(this::recompute, RECOMPUTE_DELAY_MS, TimeUnit.MILLISECONDS);
			}
			catch (RejectedExecutionException e)
			{
				recomputeQueued.set(false);
			}
		}
	}

	private void recompute()
	{
		recomputeQueued.set(false);
		final SlayerTracker t = tracker;
		if (t == null)
		{
			return;
		}
		final TrackerView.State state = !store.hasProfile() ? TrackerView.State.LOGGED_OUT
			: store.isLoaded() ? TrackerView.State.READY : TrackerView.State.LOADING;
		final double unlucky = config.unluckyPercent() / 100.0;
		final double lucky = config.luckyPercent() / 100.0;
		final TrackerView next;
		try
		{
			next = ViewBuilder.build(store.copy(), state, store.getProblem(), t.getNotice(), unlucky, lucky,
				name -> Masters.isFiller(name, 0, config.fillerAya(), config.fillerTurael(), config.fillerSpria()),
				t.getSlayerLevel(), t.getCombatLevel(), fairnessCache);
		}
		catch (RuntimeException e)
		{
			log.warn("Slayer Task Luck: couldn't build the view", e);
			return;
		}
		view = next;
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.update(next, unlucky, lucky);
			}
		});
	}

	@Provides
	SlayerTaskLuckConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerTaskLuckConfig.class);
	}

	/** Panel actions, called on the Swing thread. */
	private class Actions implements PanelActions
	{
		@Override
		public void setWanted(String group, List<String> tasks)
		{
			store.setWanted(group, tasks);
		}

		@Override
		public void setExcluded(String rollId, boolean excluded)
		{
			store.setExcluded(rollId, excluded);
		}

		@Override
		public void rescore(String group)
		{
			store.rescore(group);
		}

		@Override
		public void resetData()
		{
			store.reset();
		}

		@Override
		public void exportCsv()
		{
			final List<Filepath> chosen = new Filepath.Chooser()
				.setIsSave()
				.setAcceptsFiles()
				.setDialogTitle("Export Slayer Task Luck data")
				.addExtensionFilter("CSV file", "csv")
				.setDefaultExtension("csv")
				.setFileName("slayer-task-luck.csv")
				.showDialog(panel);
			if (chosen == null || chosen.isEmpty())
			{
				return;
			}
			final Filepath target = chosen.get(0);
			final String csv = CsvExport.build(store.copy());
			executor.execute(() ->
			{
				try
				{
					target.write(csv);
				}
				catch (IOException e)
				{
					log.warn("Slayer Task Luck: export failed", e);
					SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(panel,
						"Couldn't write the file: " + e.getMessage(), "Export failed", JOptionPane.ERROR_MESSAGE));
				}
			});
		}
	}
}

package com.slayertaskluck.math;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.SplittableRandom;
import lombok.Value;

/**
 * Do the listed odds hold up? Compares how often each task was received with how often each roll's own odds say it
 * should have been, and runs one global Monte Carlo test: replay every roll with its odds many times and see how
 * often a chi-square-style gap at least as big as the real one appears. Per-task rows are descriptive only, since
 * with many tasks a few always look off by chance.
 */
public final class Fairness
{
	@Value
	public static class Row
	{
		String task;
		int observed;
		double expected;
	}

	@Value
	public static class Result
	{
		/** Sorted by the size of the gap between observed and expected, biggest first. */
		List<Row> rows;
		double statistic;
		/** Share of simulated histories at least as uneven as the real one. Small = the odds look off. */
		double pValue;
		int simulations;
		int rolls;
	}

	private Fairness()
	{
	}

	/**
	 * @param distributions per roll: task -> chance (each summing to 1)
	 * @param outcomes per roll: the task received (a key of that roll's distribution)
	 */
	public static Result compute(List<Map<String, Double>> distributions, List<String> outcomes, int simulations, long seed)
	{
		final Map<String, Integer> index = new HashMap<>();
		final List<String> names = new ArrayList<>();
		final int n = distributions.size();
		final int[][] taskIdx = new int[n][];
		final double[][] cumulative = new double[n][];
		final int[] observedIdx = new int[n];
		int used = 0;

		for (int i = 0; i < n; i++)
		{
			final Map<String, Double> dist = distributions.get(i);
			final String outcome = outcomes.get(i);
			if (dist.isEmpty() || !dist.containsKey(outcome))
			{
				continue;
			}
			final int[] idx = new int[dist.size()];
			final double[] cum = new double[dist.size()];
			double running = 0;
			int j = 0;
			for (Map.Entry<String, Double> e : dist.entrySet())
			{
				idx[j] = index.computeIfAbsent(e.getKey(), k ->
				{
					names.add(k);
					return names.size() - 1;
				});
				running += e.getValue();
				cum[j] = running;
				j++;
			}
			cum[cum.length - 1] = Double.MAX_VALUE; // guard against rounding at the top end
			taskIdx[used] = idx;
			cumulative[used] = cum;
			observedIdx[used] = index.get(outcome);
			used++;
		}

		final int k = names.size();
		final double[] expected = new double[k];
		final int[] observed = new int[k];
		for (int i = 0; i < used; i++)
		{
			final int[] idx = taskIdx[i];
			final double[] cum = cumulative[i];
			double prev = 0;
			for (int j = 0; j < idx.length; j++)
			{
				final double c = j == idx.length - 1 ? 1.0 : cum[j];
				expected[idx[j]] += c - prev;
				prev = c;
			}
			observed[observedIdx[i]]++;
		}

		final double statistic = chiSquare(observed, expected);
		int atLeast = 0;
		final SplittableRandom random = new SplittableRandom(seed);
		final int[] counts = new int[k];
		for (int s = 0; s < simulations; s++)
		{
			Arrays.fill(counts, 0);
			for (int i = 0; i < used; i++)
			{
				final double u = random.nextDouble();
				int pos = Arrays.binarySearch(cumulative[i], u);
				if (pos < 0)
				{
					pos = -pos - 1;
				}
				counts[taskIdx[i][Math.min(pos, taskIdx[i].length - 1)]]++;
			}
			if (chiSquare(counts, expected) >= statistic - 1e-9)
			{
				atLeast++;
			}
		}

		final List<Row> rows = new ArrayList<>();
		for (int t = 0; t < k; t++)
		{
			rows.add(new Row(names.get(t), observed[t], expected[t]));
		}
		rows.sort((a, b) -> Double.compare(Math.abs(b.getObserved() - b.getExpected()), Math.abs(a.getObserved() - a.getExpected())));
		final double p = simulations > 0 ? (atLeast + 1) / (double) (simulations + 1) : Double.NaN;
		return new Result(rows, statistic, p, simulations, used);
	}

	private static double chiSquare(int[] observed, double[] expected)
	{
		double sum = 0;
		for (int t = 0; t < expected.length; t++)
		{
			if (expected[t] > 1e-12)
			{
				final double d = observed[t] - expected[t];
				sum += d * d / expected[t];
			}
		}
		return sum;
	}
}

package com.slayertaskluck.math;

import java.util.HashMap;
import java.util.Map;

/**
 * Keeps the last fairness result per master. The simulation only depends on which rolls count and the odds they were
 * rolled under, not on the wanted list or settings, so most view rebuilds (ticking a wanted task, changing a
 * threshold) reuse it instead of re-running thousands of simulated histories. Used from one thread only.
 */
public class FairnessCache
{
	private final Map<String, Long> signatures = new HashMap<>();
	private final Map<String, Fairness.Result> results = new HashMap<>();

	Fairness.Result get(String group, long signature)
	{
		final Long known = signatures.get(group);
		return known != null && known == signature ? results.get(group) : null;
	}

	void put(String group, long signature, Fairness.Result result)
	{
		signatures.put(group, signature);
		results.put(group, result);
	}
}

package com.slayertaskluck.math;

import lombok.Builder;
import lombok.Value;

/** Everything the panel and overlay show for one master (or all masters). Immutable. */
@Value
@Builder
public class GroupStats
{
	String group;
	String name;
	boolean allMasters;

	/** Target rolls that count toward luck. */
	int rolls;
	/** Target rolls left out (excluded by the user, or no usable odds). */
	int uncounted;

	int dryRolls;
	double dryProbability;
	Verdict dryVerdict;
	int longestDry;
	double longestDryProbability;

	int observed;
	double expected;
	double sd;
	double z;
	double percentile;
	Verdict luckVerdict;

	/** Filler tasks since the last wanted task, and the time they took. */
	int detours;
	long detourMillis;
	int totalDetours;
	long totalDetourMillis;

	/** Chance per roll right now (latest odds and wanted tasks), or null when unknown. */
	Double chancePerRoll;

	/** Cumulative (observed - expected) and its standard deviation after each counted roll. */
	double[] chartDiff;
	double[] chartSd;

	Fairness.Result fairness;
	int fairnessMinimum;

	public boolean hasLuckData()
	{
		return rolls > 0 && expected > 0;
	}
}

package com.slayertaskluck.math;

/**
 * Pure luck statistics with no RuneLite dependencies. Every roll {@code i} at a target master has a chance
 * {@code p[i]} of giving a wanted task.
 */
public final class LuckMath
{
	private LuckMath()
	{
	}

	/**
	 * Chance of going this many rolls (or more) without a wanted task: the product of (1 - p_i) over the rolls
	 * since the last wanted task.
	 */
	public static double dryStreakProbability(double[] wantedChances)
	{
		double probability = 1.0;
		for (double p : wantedChances)
		{
			check(p);
			probability *= 1.0 - p;
		}
		return probability;
	}

	/**
	 * Exact distribution of the number of wanted tasks over rolls with different chances (Poisson-binomial),
	 * by the standard O(n^2) dynamic program. {@code pmf[k]} = P(exactly k wanted).
	 */
	public static double[] poissonBinomial(double[] p)
	{
		final double[] pmf = new double[p.length + 1];
		pmf[0] = 1.0;
		for (int i = 0; i < p.length; i++)
		{
			check(p[i]);
			final double q = 1.0 - p[i];
			for (int k = i + 1; k >= 1; k--)
			{
				pmf[k] = pmf[k] * q + pmf[k - 1] * p[i];
			}
			pmf[0] *= q;
		}
		return pmf;
	}

	/** P(X <= k). */
	public static double cdf(double[] pmf, int k)
	{
		double sum = 0;
		for (int i = 0; i <= k && i < pmf.length; i++)
		{
			sum += pmf[i];
		}
		return Math.min(1.0, sum);
	}

	/**
	 * Mid-p percentile: P(X < k) + P(X = k) / 2. Unlike P(X <= k) it puts an exactly average result near 50%,
	 * which matters for small whole-number counts. Low = unlucky, high = lucky.
	 */
	public static double midP(double[] pmf, int observed)
	{
		final double below = cdf(pmf, observed - 1);
		final double at = observed >= 0 && observed < pmf.length ? pmf[observed] : 0;
		return Math.max(0, Math.min(1, below + at / 2));
	}

	/**
	 * Chance that somewhere in this sequence of rolls there is a run of at least {@code length} rolls in a row
	 * without a wanted task. O(n * length) dynamic program over the current run length.
	 */
	public static double longestDryAtLeast(double[] p, int length)
	{
		if (length <= 0)
		{
			return 1.0;
		}
		double[] run = new double[length]; // run[r] = P(no run of `length` yet, current dry run = r)
		run[0] = 1.0;
		double reached = 0;
		for (double pi : p)
		{
			check(pi);
			final double q = 1.0 - pi;
			final double[] next = new double[length];
			double alive = 0;
			for (double v : run)
			{
				alive += v;
			}
			next[0] = alive * pi;
			for (int r = 0; r < length - 1; r++)
			{
				next[r + 1] = run[r] * q;
			}
			reached += run[length - 1] * q;
			run = next;
		}
		return Math.min(1.0, reached);
	}

	private static void check(double p)
	{
		if (!(p >= 0 && p <= 1)) // also rejects NaN
		{
			throw new IllegalArgumentException("probability out of range: " + p);
		}
	}
}

package com.slayertaskluck.math;

import com.slayertaskluck.model.OddsSnapshot;
import com.slayertaskluck.model.Roll;
import com.slayertaskluck.model.TrackerData;
import com.slayertaskluck.tracking.OddsModel;
import com.slayertaskluck.tracking.RollScorer;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** Builds {@link GroupStats} from saved data. Pure; runs on the plugin's background thread. */
public final class StatsCalculator
{
	/** Fairness needs this many counted rolls at a master before it says anything. */
	public static final int FAIRNESS_MINIMUM = 50;
	/** One detour longer than this (e.g. logged out overnight) is capped so time totals stay meaningful. */
	static final long MAX_DETOUR_MS = 2 * 60 * 60 * 1000L;
	/** Simulated rolls per fairness run (simulations x rolls). 1,000+ simulations is plenty for a fair/unusual verdict. */
	private static final long SIMULATION_BUDGET = 4_000_000L;
	private static final int MAX_SIMULATIONS = 20_000;
	private static final int MIN_SIMULATIONS = 500;

	private StatsCalculator()
	{
	}

	public static GroupStats compute(TrackerData data, String group, String name, double unluckyCut, double luckyCut,
		boolean withFairness)
	{
		return compute(data, group, name, unluckyCut, luckyCut, withFairness, null);
	}

	/**
	 * @param group master group, or null for all masters
	 * @param cache reuses the fairness result while the counted rolls are unchanged; may be null
	 */
	public static GroupStats compute(TrackerData data, String group, String name, double unluckyCut, double luckyCut,
		boolean withFairness, FairnessCache cache)
	{
		final List<Roll> all = new ArrayList<>(data.getRolls());
		all.sort(Comparator.comparingLong(Roll::getTimestamp));

		final List<Roll> counted = new ArrayList<>();
		int uncounted = 0;
		for (Roll r : all)
		{
			if (r.isFiller() || (group != null && !group.equals(r.getMasterGroup())))
			{
				continue;
			}
			if (r.countsForLuck())
			{
				counted.add(r);
			}
			else
			{
				uncounted++;
			}
		}

		final int n = counted.size();
		final double[] p = new double[n];
		int observed = 0;
		double expected = 0;
		double variance = 0;
		final double[] chartDiff = new double[n];
		final double[] chartSd = new double[n];
		int run = 0;
		int longest = 0;
		for (int i = 0; i < n; i++)
		{
			final Roll r = counted.get(i);
			p[i] = r.getPWanted();
			final boolean hit = Boolean.TRUE.equals(r.getWanted());
			observed += hit ? 1 : 0;
			expected += p[i];
			variance += p[i] * (1 - p[i]);
			chartDiff[i] = observed - expected;
			chartSd[i] = Math.sqrt(variance);
			run = hit ? 0 : run + 1;
			longest = Math.max(longest, run);
		}

		// Current dry streak: rolls since the last wanted one.
		int dry = 0;
		double dryProb = 1;
		for (int i = n - 1; i >= 0 && !Boolean.TRUE.equals(counted.get(i).getWanted()); i--)
		{
			dry++;
			dryProb *= 1 - p[i];
		}

		final double sd = Math.sqrt(variance);
		final Verdict luck;
		double percentile = Double.NaN;
		if (n > 0 && expected > 0)
		{
			percentile = LuckMath.midP(LuckMath.poissonBinomial(p), observed);
			luck = Verdict.fromPercentile(percentile, unluckyCut, luckyCut);
		}
		else
		{
			luck = Verdict.NONE;
		}
		final Verdict dryVerdict = n > 0 && expected > 0 ? Verdict.unluckySide(dryProb, unluckyCut) : Verdict.NONE;

		// Detours: filler tasks after the last wanted roll in scope, timed until the next assignment.
		int detours = 0;
		long detourMs = 0;
		int totalDetours = 0;
		long totalDetourMs = 0;
		for (int i = 0; i < all.size(); i++)
		{
			final Roll r = all.get(i);
			if (r.isFiller())
			{
				final long ms = i + 1 < all.size()
					? Math.min(MAX_DETOUR_MS, Math.max(0, all.get(i + 1).getTimestamp() - r.getTimestamp()))
					: 0;
				detours++;
				detourMs += ms;
				totalDetours++;
				totalDetourMs += ms;
			}
			else if (r.countsForLuck() && Boolean.TRUE.equals(r.getWanted())
				&& (group == null || group.equals(r.getMasterGroup())))
			{
				detours = 0;
				detourMs = 0;
			}
		}

		final GroupStats.GroupStatsBuilder b = GroupStats.builder()
			.group(group)
			.name(name)
			.allMasters(group == null)
			.rolls(n)
			.uncounted(uncounted)
			.dryRolls(dry)
			.dryProbability(dryProb)
			.dryVerdict(dryVerdict)
			.longestDry(longest)
			.longestDryProbability(n > 0 ? LuckMath.longestDryAtLeast(p, longest) : 1)
			.observed(observed)
			.expected(expected)
			.sd(sd)
			.z(sd > 0 ? (observed - expected) / sd : 0)
			.percentile(percentile)
			.luckVerdict(luck)
			.detours(detours)
			.detourMillis(detourMs)
			.totalDetours(totalDetours)
			.totalDetourMillis(totalDetourMs)
			.chartDiff(chartDiff)
			.chartSd(chartSd)
			.fairnessMinimum(FAIRNESS_MINIMUM);

		if (group != null)
		{
			final List<OddsSnapshot> snaps = RollScorer.snapshotsNewestFirst(data, group);
			final Map<String, Integer> borrowed = OddsModel.learnedWeights(snaps);
			if (!snaps.isEmpty())
			{
				final Map<String, Double> now = OddsModel.distribution(snaps.get(0), null, borrowed);
				final List<String> wanted = data.getWanted().getOrDefault(group, Collections.emptyList());
				b.chancePerRoll(OddsModel.score(now, "", wanted).getPWanted());
			}
			if (withFairness && n >= FAIRNESS_MINIMUM)
			{
				b.fairness(fairness(group, counted, snaps, borrowed, cache));
			}
		}
		return b.build();
	}

	private static Fairness.Result fairness(String group, List<Roll> counted, List<OddsSnapshot> snaps,
		Map<String, Integer> borrowed, FairnessCache cache)
	{
		// The result depends only on which rolls count and their odds, not on the wanted list.
		long signature = counted.size();
		for (Roll r : counted)
		{
			signature = signature * 31 + r.getId().hashCode();
			signature = signature * 31 + Objects.hashCode(r.getSnapshotId());
			signature = signature * 31 + Objects.hashCode(r.getExcludedTask());
		}
		for (OddsSnapshot s : snaps)
		{
			signature = signature * 31 + s.getId().hashCode();
		}
		if (cache != null)
		{
			final Fairness.Result cached = cache.get(group, signature);
			if (cached != null)
			{
				return cached;
			}
		}

		final Map<String, OddsSnapshot> byId = new HashMap<>();
		for (OddsSnapshot s : snaps)
		{
			byId.put(s.getId(), s);
		}
		final List<Map<String, Double>> dists = new ArrayList<>();
		final List<String> outcomes = new ArrayList<>();
		for (Roll r : counted)
		{
			final OddsSnapshot s = byId.get(r.getSnapshotId());
			if (s == null)
			{
				continue;
			}
			final Map<String, Double> dist = OddsModel.distribution(s, r.getExcludedTask(), borrowed);
			final OddsModel.Scored scored = OddsModel.score(dist, r.getTask(), Collections.emptyList());
			if (scored.getMatched() != null)
			{
				dists.add(dist);
				outcomes.add(scored.getMatched());
			}
		}
		final int sims = (int) Math.max(MIN_SIMULATIONS, Math.min(MAX_SIMULATIONS, SIMULATION_BUDGET / Math.max(1, dists.size())));
		// Fixed seed per data size: the result doesn't flicker between redraws.
		final Fairness.Result result = Fairness.compute(dists, outcomes, sims, 0x5EED + dists.size());
		if (cache != null)
		{
			cache.put(group, signature, result);
		}
		return result;
	}
}

package com.slayertaskluck.math;

import java.text.DecimalFormat;
import lombok.Value;

/** A plain-language luck verdict plus how rare the result is ("1 in N"). */
@Value
public class Verdict
{
	public enum Tone
	{
		UNLUCKY("unlucky"),
		NORMAL("normal"),
		LUCKY("lucky"),
		NONE("no data");

		private final String word;

		Tone(String word)
		{
			this.word = word;
		}

		public String word()
		{
			return word;
		}
	}

	public static final Verdict NONE = new Verdict(Tone.NONE, Double.NaN);

	Tone tone;
	/** Chance of a result at least this extreme on the side it falls on. */
	double tail;

	/** Verdict for a one-sided result (a dry streak can only be unlucky). */
	public static Verdict unluckySide(double tail, double unluckyCut)
	{
		return new Verdict(tail <= unluckyCut ? Tone.UNLUCKY : Tone.NORMAL, tail);
	}

	/** Verdict from a mid-p percentile (low = unlucky, high = lucky). */
	public static Verdict fromPercentile(double midP, double unluckyCut, double luckyCut)
	{
		if (midP <= unluckyCut)
		{
			return new Verdict(Tone.UNLUCKY, midP);
		}
		if (1 - midP <= luckyCut)
		{
			return new Verdict(Tone.LUCKY, 1 - midP);
		}
		return new Verdict(Tone.NORMAL, Math.min(midP, 1 - midP));
	}

	public boolean isTinted()
	{
		return tone == Tone.UNLUCKY || tone == Tone.LUCKY;
	}

	/** "1 in 16" for tinted results, "normal" otherwise. */
	public String chip()
	{
		return isTinted() ? oneIn(tail) : tone.word();
	}

	public static String oneIn(double probability)
	{
		if (!(probability > 0))
		{
			return "1 in a lot";
		}
		final double n = 1 / probability;
		if (n < 100)
		{
			return "1 in " + Math.max(1, Math.round(n));
		}
		if (n < 1_000_000)
		{
			// two significant figures keeps big numbers honest without fake precision
			final double magnitude = Math.pow(10, Math.floor(Math.log10(n)) - 1);
			return "1 in " + new DecimalFormat("#,###").format(Math.round(n / magnitude) * magnitude);
		}
		return "1 in " + new DecimalFormat("0.#").format(n / 1_000_000) + "M";
	}
}

package com.slayertaskluck.model;

/** How much the odds attached to a roll can be trusted. */
public enum Confidence
{
	/** Odds from a snapshot that still matches the player's state. */
	CURRENT,
	/** Odds from a snapshot that may be out of date (levels or blocklist changed since). Still counted, but flagged. */
	STALE,
	/** No usable odds. Shown in history, left out of the luck math. */
	NONE
}

