package com.slayertaskluck.model;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Data;

/** Everything stored for one RuneScape profile (account + world type). Saved as one JSON file. */
@Data
public class TrackerData
{
	public static final int SCHEMA_VERSION = 1;

	private int schemaVersion = SCHEMA_VERSION;
	private List<OddsSnapshot> snapshots = new ArrayList<>();
	private List<Roll> rolls = new ArrayList<>();
	/** Wanted task names per master group. */
	private Map<String, List<String>> wanted = new HashMap<>();
	/** Last display name seen per master group. */
	private Map<String, String> masterNames = new HashMap<>();
	/** Blocked task names from the rewards Tasks tab (account-wide), and when that list last changed. */
	private List<String> blocked = new ArrayList<>();
	private long blockedChangedAt;

	/**
	 * Copy that is safe to hand to another thread. Rolls are copied (they change when excluded or re-scored);
	 * snapshots are shared because they are never modified after being stored.
	 */
	public TrackerData copy()
	{
		final TrackerData d = new TrackerData();
		d.schemaVersion = schemaVersion;
		d.snapshots = new ArrayList<>(snapshots);
		d.rolls = new ArrayList<>(rolls.size());
		for (Roll r : rolls)
		{
			d.rolls.add(r.copy());
		}
		d.wanted = new HashMap<>();
		for (Map.Entry<String, List<String>> e : wanted.entrySet())
		{
			d.wanted.put(e.getKey(), new ArrayList<>(e.getValue()));
		}
		d.masterNames = new HashMap<>(masterNames);
		d.blocked = new ArrayList<>(blocked);
		d.blockedChangedAt = blockedChangedAt;
		return d;
	}
}

package com.slayertaskluck.tracking;

import com.slayertaskluck.model.Roll;
import com.slayertaskluck.model.TrackerData;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Date;
import java.util.List;
import java.util.Locale;
import java.util.TimeZone;

/** Every logged task as CSV, oldest first. */
public final class CsvExport
{
	private CsvExport()
	{
	}

	public static String build(TrackerData data)
	{
		final SimpleDateFormat iso = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'", Locale.ROOT);
		iso.setTimeZone(TimeZone.getTimeZone("UTC"));
		final StringBuilder sb = new StringBuilder();
		sb.append("time_utc,master,master_group,task,amount,filler,wanted,chance_of_task,chance_of_wanted,confidence,excluded,note\n");
		final List<Roll> rolls = new ArrayList<>(data.getRolls());
		rolls.sort(Comparator.comparingLong(Roll::getTimestamp));
		for (Roll r : rolls)
		{
			sb.append(iso.format(new Date(r.getTimestamp()))).append(',')
				.append(cell(r.getMasterName())).append(',')
				.append(cell(r.getMasterGroup())).append(',')
				.append(cell(r.getTask())).append(',')
				.append(r.getAmount()).append(',')
				.append(r.isFiller()).append(',')
				.append(r.getWanted() == null ? "" : r.getWanted()).append(',')
				.append(r.getPTask() == null ? "" : String.format(Locale.ROOT, "%.6f", r.getPTask())).append(',')
				.append(r.getPWanted() == null ? "" : String.format(Locale.ROOT, "%.6f", r.getPWanted())).append(',')
				.append(r.getConfidence() == null ? "" : r.getConfidence()).append(',')
				.append(r.isExcluded()).append(',')
				.append(cell(r.getConfidenceNote())).append('\n');
		}
		return sb.toString();
	}

	private static String cell(String s)
	{
		if (s == null)
		{
			return "";
		}
		if (s.contains(",") || s.contains("\"") || s.contains("\n"))
		{
			return '"' + s.replace("\"", "\"\"") + '"';
		}
		return s;
	}
}

package com.slayertaskluck.tracking;

import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Slayer master names and groups. Masters that share a role (Duradel/Kuradal, Turael/Aya, Nieve/Steve) are grouped
 * so stats carry over, while the name the game shows is kept for display.
 */
public final class Masters
{
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");
	private static final Map<String, String> GROUP_BY_NAME = new HashMap<>();
	/** Group key to the name shown for it, easiest master first. */
	private static final Map<String, String> GROUPS = new LinkedHashMap<>();

	static
	{
		group("Turael", "Aya");
		group("Spria");
		group("Mazchna", "Achtryn Vis");
		group("Vannaka");
		group("Chaeldar");
		group("Konar", "Konar quo Maten");
		group("Nieve", "Steve");
		group("Duradel", "Kuradal");
		group("Krystilia");
	}

	private Masters()
	{
	}

	/** A group is keyed by its first master's lower-case name ("Duradel" and "Kuradal" are "duradel"). */
	private static void group(String... names)
	{
		final String group = names[0].toLowerCase(Locale.ROOT);
		GROUPS.put(group, names[0]);
		for (String name : names)
		{
			GROUP_BY_NAME.put(name.toLowerCase(Locale.ROOT), group);
		}
	}

	/** Every master group (key to display name), easiest master first. */
	public static Map<String, String> groups()
	{
		return Collections.unmodifiableMap(GROUPS);
	}

	/** Strips colour tags and non-breaking spaces from a name the game shows. */
	public static String cleanName(String raw)
	{
		if (raw == null)
		{
			return null;
		}
		final String clean = TAGS.matcher(raw).replaceAll("").replace(' ', ' ').trim();
		return clean.isEmpty() ? null : clean;
	}

	public static boolean isKnownMaster(String name)
	{
		return name != null && GROUP_BY_NAME.containsKey(name.toLowerCase(Locale.ROOT));
	}

	/** Group key for stats. Unknown masters get their own group; an unknown name falls back to the role slot. */
	public static String groupOf(String name, int slot)
	{
		if (name != null)
		{
			final String lower = name.toLowerCase(Locale.ROOT);
			return GROUP_BY_NAME.getOrDefault(lower, lower);
		}
		return "slot" + slot;
	}

	public static String fallbackName(int slot)
	{
		return "Slayer master " + slot;
	}

	/**
	 * Whether a master counts as a filler (its tasks are skips, never luck rolls). Decided by name from settings.
	 * Without a name, slot 1 (Turael's role) counts as filler when Aya or Turael is enabled.
	 */
	public static boolean isFiller(String name, int slot, boolean aya, boolean turael, boolean spria)
	{
		if (name == null)
		{
			return slot == 1 && (aya || turael);
		}
		switch (name.toLowerCase(Locale.ROOT))
		{
			case "aya":
				return aya;
			case "turael":
				return turael;
			case "spria":
				return spria;
			default:
				return false;
		}
	}
}

package com.slayertaskluck.tracking;

import com.slayertaskluck.model.OddsSnapshot;
import com.slayertaskluck.model.SnapshotEntry;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import lombok.Value;

/** Turns task-list snapshots into roll probabilities. Pure logic, no game access. */
public final class OddsModel
{
	public static final String BOSS = "Boss";

	private OddsModel()
	{
	}

	/** Builds a snapshot from parsed rows, recovering exact weights when possible. */
	public static OddsSnapshot buildSnapshot(String masterGroup, String masterName, long timestamp,
		int slayerLevel, int combatLevel, List<SnapshotEntry> entries, String heldTask)
	{
		final int[] permille = new int[entries.size()];
		for (int i = 0; i < permille.length; i++)
		{
			permille[i] = OddsParser.toPermille(entries.get(i).getShownPercent());
		}
		final int[] weights = WeightInference.infer(permille);
		int total = 0;
		for (int i = 0; i < permille.length; i++)
		{
			final int w = weights != null ? weights[i] : permille[i];
			entries.get(i).setWeight(w);
			total += w;
		}

		final OddsSnapshot s = new OddsSnapshot();
		s.setId(UUID.randomUUID().toString());
		s.setMasterGroup(masterGroup);
		s.setMasterName(masterName);
		s.setTimestamp(timestamp);
		s.setSlayerLevel(slayerLevel);
		s.setCombatLevel(combatLevel);
		s.setEntries(entries);
		s.setWeightsExact(weights != null);
		s.setTotalWeight(total);
		final SnapshotEntry held = heldTask == null ? null : find(s, heldTask);
		s.setHeldTask(held != null ? held.getName() : null);
		s.setContentHash(hash(entries, s.getHeldTask()));
		return s;
	}

	/** Normalised key for matching task names across sources ("Kalphite"/"Kalphites", "TzHaar"/"Tzhaar"). */
	public static String key(String name)
	{
		if (name == null)
		{
			return "";
		}
		String k = name.toLowerCase(Locale.ROOT).replaceAll("[^a-z]", "");
		if (k.endsWith("s"))
		{
			k = k.substring(0, k.length() - 1);
		}
		return k;
	}

	public static SnapshotEntry find(OddsSnapshot s, String task)
	{
		final String k = key(task);
		for (SnapshotEntry e : s.getEntries())
		{
			if (key(e.getName()).equals(k))
			{
				return e;
			}
		}
		return null;
	}

	/**
	 * Weights the game would use for a roll: every available task in the snapshot, plus the task held while the
	 * snapshot was taken (shown as 0% then; weight borrowed from another exact snapshot), minus the task held at
	 * roll time.
	 */
	public static Map<String, Integer> rollWeights(OddsSnapshot s, String excludedTask, Map<String, Integer> borrowed)
	{
		final Map<String, Integer> weights = new LinkedHashMap<>();
		for (SnapshotEntry e : s.getEntries())
		{
			if (e.getWeight() > 0)
			{
				weights.put(e.getName(), e.getWeight());
			}
		}
		if (s.getHeldTask() != null && !weights.containsKey(s.getHeldTask()) && s.isWeightsExact() && borrowed != null)
		{
			final Integer w = borrowed.get(key(s.getHeldTask()));
			if (w != null && w > 0)
			{
				weights.put(s.getHeldTask(), w);
			}
		}
		if (excludedTask != null)
		{
			final SnapshotEntry ex = find(s, excludedTask);
			if (ex != null)
			{
				weights.remove(ex.getName());
			}
		}
		return weights;
	}

	/** Probability distribution (task name -> chance) for a roll. */
	public static Map<String, Double> distribution(OddsSnapshot s, String excludedTask, Map<String, Integer> borrowed)
	{
		final Map<String, Integer> weights = rollWeights(s, excludedTask, borrowed);
		long total = 0;
		for (int w : weights.values())
		{
			total += w;
		}
		final Map<String, Double> dist = new LinkedHashMap<>();
		if (total == 0)
		{
			return dist;
		}
		for (Map.Entry<String, Integer> e : weights.entrySet())
		{
			dist.put(e.getKey(), e.getValue() / (double) total);
		}
		return dist;
	}

	/** Exact weights by task key from the given exact snapshots, newest first wins. */
	public static Map<String, Integer> learnedWeights(Collection<OddsSnapshot> newestFirst)
	{
		final Map<String, Integer> learned = new HashMap<>();
		for (OddsSnapshot s : newestFirst)
		{
			if (!s.isWeightsExact())
			{
				continue;
			}
			for (SnapshotEntry e : s.getEntries())
			{
				if (e.getWeight() > 0)
				{
					learned.putIfAbsent(key(e.getName()), e.getWeight());
				}
			}
		}
		return learned;
	}

	/** Whether the snapshot is missing a weight it needs (held task with nothing to borrow from). */
	public static boolean missingHeldWeight(OddsSnapshot s, String excludedTask, Map<String, Integer> borrowed)
	{
		if (s.getHeldTask() == null || key(s.getHeldTask()).equals(key(excludedTask)))
		{
			return false;
		}
		return !s.isWeightsExact() || borrowed == null || !borrowed.containsKey(key(s.getHeldTask()));
	}

	/** Result of scoring one roll against a distribution. */
	@Value
	public static class Scored
	{
		/** Name of the matched list row, or null when the received task isn't on the list. */
		String matched;
		double pTask;
		double pWanted;
		boolean wanted;
	}

	/**
	 * Scores a received task against a distribution and a wanted set. Boss tasks are assigned as the specific boss,
	 * so a task that isn't on the list falls back to the list's "Boss" row when that row is possible.
	 */
	public static Scored score(Map<String, Double> dist, String receivedTask, Collection<String> wantedNames)
	{
		String matched = null;
		final String k = key(receivedTask);
		for (String name : dist.keySet())
		{
			if (key(name).equals(k))
			{
				matched = name;
				break;
			}
		}
		if (matched == null && dist.containsKey(BOSS))
		{
			matched = BOSS;
		}

		final Set<String> wantedKeys = new HashSet<>();
		if (wantedNames != null)
		{
			for (String w : wantedNames)
			{
				wantedKeys.add(key(w));
			}
		}
		double pWanted = 0;
		boolean wanted = false;
		for (Map.Entry<String, Double> e : dist.entrySet())
		{
			if (wantedKeys.contains(key(e.getKey())))
			{
				pWanted += e.getValue();
				if (e.getKey().equals(matched))
				{
					wanted = true;
				}
			}
		}
		final double pTask = matched != null ? dist.get(matched) : 0;
		return new Scored(matched, pTask, Math.min(1.0, pWanted), wanted);
	}

	private static String hash(List<SnapshotEntry> entries, String held)
	{
		final StringBuilder sb = new StringBuilder();
		for (SnapshotEntry e : entries)
		{
			sb.append(e.getName()).append('=').append(OddsParser.toPermille(e.getShownPercent())).append(';');
		}
		sb.append("held=").append(held);
		try
		{
			final byte[] digest = MessageDigest.getInstance("SHA-256").digest(sb.toString().getBytes(StandardCharsets.UTF_8));
			final StringBuilder hex = new StringBuilder();
			for (int i = 0; i < 8; i++)
			{
				hex.append(String.format("%02x", digest[i]));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			return Integer.toHexString(sb.toString().hashCode());
		}
	}
}

package com.slayertaskluck.tracking;

import com.slayertaskluck.model.SnapshotEntry;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses the Slayer task list ("Slayer Tasks" interface). Rows appear as a name text such as
 * {@code "Gargoyles (130-200)"} or {@code "Boss (Varies)"} followed, a few widgets later, by {@code "4.9%"}.
 * Pairing by pattern rather than by fixed child index keeps this working if the layout shifts.
 */
public final class OddsParser
{
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");
	private static final Pattern NAME = Pattern.compile("^(.+?)\\s*\\((?:(\\d+)\\s*-\\s*(\\d+)|[A-Za-z ]+)\\)$");
	private static final Pattern PERCENT = Pattern.compile("^(\\d{1,3}(?:\\.\\d+)?)\\s*%$");

	private OddsParser()
	{
	}

	public static List<SnapshotEntry> parse(List<String> texts)
	{
		final List<SnapshotEntry> entries = new ArrayList<>();
		SnapshotEntry pending = null;
		for (String raw : texts)
		{
			if (raw == null)
			{
				continue;
			}
			final String text = TAGS.matcher(raw).replaceAll("").replace(' ', ' ').trim();
			if (text.isEmpty())
			{
				continue;
			}

			final Matcher percent = PERCENT.matcher(text);
			if (percent.matches())
			{
				if (pending != null)
				{
					pending.setShownPercent(Double.parseDouble(percent.group(1)));
					entries.add(pending);
					pending = null;
				}
				continue;
			}

			final Matcher name = NAME.matcher(text);
			if (name.matches())
			{
				pending = new SnapshotEntry();
				pending.setName(name.group(1).trim());
				if (name.group(2) != null)
				{
					pending.setMin(Integer.parseInt(name.group(2)));
					pending.setMax(Integer.parseInt(name.group(3)));
				}
			}
		}
		return entries;
	}

	/** Shown percentage as an integer number of tenths of a percent (per-mille), e.g. 4.9% -> 49. */
	public static int toPermille(double shownPercent)
	{
		return (int) Math.round(shownPercent * 10);
	}
}

package com.slayertaskluck.tracking;

import lombok.Builder;
import lombok.Value;

/** What the tracker saw when a task was assigned, before odds are attached. */
@Value
@Builder
public class RollDraft
{
	long timestamp;
	String masterName;
	int masterSlot;
	String masterGroup;
	String task;
	int taskId;
	int amount;
	int area;
	boolean filler;
	/** Task held at roll time (still active), which the game leaves out of the roll. */
	String excludedTask;
	int slayerLevel;
	int combatLevel;
}

package com.slayertaskluck.tracking;

import com.slayertaskluck.model.Confidence;
import com.slayertaskluck.model.OddsSnapshot;
import com.slayertaskluck.model.Roll;
import com.slayertaskluck.model.TrackerData;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/** Attaches odds to rolls from the saved snapshots. Pure logic over {@link TrackerData}. */
public final class RollScorer
{
	private RollScorer()
	{
	}

	public static Roll build(TrackerData data, RollDraft d)
	{
		final Roll r = new Roll();
		r.setId(UUID.randomUUID().toString());
		r.setTimestamp(d.getTimestamp());
		r.setMasterGroup(d.getMasterGroup());
		r.setMasterName(d.getMasterName());
		r.setMasterSlot(d.getMasterSlot());
		r.setTask(d.getTask());
		r.setTaskId(d.getTaskId());
		r.setAmount(d.getAmount());
		r.setArea(d.getArea());
		r.setFiller(d.isFiller());
		r.setExcludedTask(d.getExcludedTask());
		r.setSlayerLevel(d.getSlayerLevel());
		r.setCombatLevel(d.getCombatLevel());
		if (!r.isFiller())
		{
			score(data, r);
		}
		return r;
	}

	/** (Re)computes the odds of a target roll from the snapshot in effect when it was rolled. */
	public static void score(TrackerData data, Roll r)
	{
		r.setSnapshotId(null);
		r.setPTask(null);
		r.setPWanted(null);
		r.setWanted(null);

		final List<OddsSnapshot> group = snapshotsNewestFirst(data, r.getMasterGroup());
		OddsSnapshot snap = null;
		for (OddsSnapshot s : group)
		{
			if (s.getTimestamp() <= r.getTimestamp())
			{
				snap = s;
				break;
			}
		}
		if (snap == null)
		{
			r.setConfidence(Confidence.NONE);
			r.setConfidenceNote("No task list saved for this master yet");
			return;
		}
		r.setSnapshotId(snap.getId());

		final Map<String, Integer> borrowed = OddsModel.learnedWeights(group);
		final Map<String, Double> dist = OddsModel.distribution(snap, r.getExcludedTask(), borrowed);
		final List<String> wanted = data.getWanted().getOrDefault(r.getMasterGroup(), Collections.emptyList());
		final OddsModel.Scored scored = OddsModel.score(dist, r.getTask(), wanted);
		if (scored.getMatched() == null)
		{
			r.setConfidence(Confidence.NONE);
			r.setConfidenceNote("Not on the saved task list; open the list again");
			return;
		}

		r.setPTask(scored.getPTask());
		r.setPWanted(scored.getPWanted());
		r.setWanted(scored.isWanted());

		final List<String> stale = new ArrayList<>();
		if (r.getSlayerLevel() > 0 && snap.getSlayerLevel() > 0 && r.getSlayerLevel() != snap.getSlayerLevel())
		{
			stale.add("Slayer level changed");
		}
		if (r.getCombatLevel() > 0 && snap.getCombatLevel() > 0 && r.getCombatLevel() != snap.getCombatLevel())
		{
			stale.add("combat level changed");
		}
		if (data.getBlockedChangedAt() > snap.getTimestamp() && data.getBlockedChangedAt() <= r.getTimestamp())
		{
			stale.add("blocklist changed");
		}
		if (OddsModel.missingHeldWeight(snap, r.getExcludedTask(), borrowed))
		{
			stale.add("list was opened during a " + snap.getHeldTask() + " task");
		}
		if (!snap.isWeightsExact())
		{
			stale.add("approximate odds");
		}

		final List<String> notes = new ArrayList<>();
		if (OddsModel.BOSS.equals(scored.getMatched()) && !OddsModel.key(r.getTask()).equals(OddsModel.key(OddsModel.BOSS)))
		{
			notes.add("counted as a Boss task");
		}
		if (wanted.isEmpty())
		{
			notes.add("no wanted tasks picked yet");
		}
		if (stale.isEmpty())
		{
			r.setConfidence(Confidence.CURRENT);
		}
		else
		{
			r.setConfidence(Confidence.STALE);
			notes.addAll(0, stale);
		}
		r.setConfidenceNote(notes.isEmpty() ? null : capitalize(String.join(", ", notes)));
	}

	public static List<OddsSnapshot> snapshotsNewestFirst(TrackerData data, String group)
	{
		final List<OddsSnapshot> list = new ArrayList<>();
		for (OddsSnapshot s : data.getSnapshots())
		{
			if (s.getMasterGroup() != null && s.getMasterGroup().equals(group))
			{
				list.add(s);
			}
		}
		list.sort((a, b) -> Long.compare(b.getTimestamp(), a.getTimestamp()));
		return list;
	}

	private static String capitalize(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.slayertaskluck.tracking;

import com.slayertaskluck.SlayerTaskLuckConfig;
import com.slayertaskluck.model.OddsSnapshot;
import com.slayertaskluck.model.SnapshotEntry;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

/**
 * Watches the game (read-only) for Slayer task assignments and task-list openings, all on the client thread.
 *
 * <p>Detection (see docs/DESIGN.md): a new assignment changes {@code SLAYER_TARGET}
 * and/or {@code SLAYER_COUNT_ORIGINAL} within one tick; kills only lower {@code SLAYER_COUNT}. Changes are
 * collected and read back one tick later, so every value (and the master's dialogue line) has arrived. The values
 * the client loads at login or after a world hop are taken as the baseline, never as an assignment.
 */
@Slf4j
public class SlayerTracker
{
	private static final int LOGIN_SETTLE_TICKS = 3;
	/** A dialogue line this recent names the master who assigned the task. */
	private static final int SPEAKER_TICKS = 15;
	/** A master clicked or talked to this recently owns the task list that just opened. */
	private static final int MASTER_TICKS = 100;
	/** How long after talking to a master the overlay counts as "while skipping". */
	private static final int CONTEXT_TICKS = 15;
	private static final Pattern SLOT = Pattern.compile("^Slot \\d+:?$");

	private final Client client;
	private final TrackerStore store;
	private final SlayerTaskLuckConfig config;
	private final Runnable onNotice;
	private final Map<Integer, String> taskNames = new HashMap<>();

	private boolean expectReload = true;
	private int settleTicks;
	private boolean haveBaseline;
	private int baseTarget;
	private int baseOriginal;
	private int baseCount;
	private String baseStored;
	private int pendingTick = -1;

	private String lastSpeaker;
	private int lastSpeakerTick = -10_000;
	private String lastMaster;
	private int lastMasterTick = -10_000;
	private int listReadTick = -1;
	private int rewardsReadTick = -1;
	private Boolean currentTaskFiller;

	private volatile boolean skippingContext;
	private volatile int slayerLevel;
	private volatile int combatLevel;
	private volatile String notice;

	public SlayerTracker(Client client, TrackerStore store, SlayerTaskLuckConfig config, Runnable onNotice)
	{
		this.client = client;
		this.store = store;
		this.config = config;
		this.onNotice = onNotice;
	}

	/** Call on the client thread when the plugin starts. */
	public void start()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			expectReload = false;
			captureBaseline();
		}
	}

	public boolean isSkippingContext()
	{
		return skippingContext;
	}

	public int getSlayerLevel()
	{
		return slayerLevel;
	}

	public int getCombatLevel()
	{
		return combatLevel;
	}

	/** A one-off message for the panel (e.g. a list we couldn't attribute), or null. */
	public String getNotice()
	{
		return notice;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case LOGGING_IN:
			case HOPPING:
			case CONNECTION_LOST:
				expectReload = true;
				haveBaseline = false;
				pendingTick = -1;
				break;
			case LOGGED_IN:
				// LOGGED_IN also follows every loading screen; only a real login or hop reloads the varps.
				if (expectReload)
				{
					expectReload = false;
					settleTicks = LOGIN_SETTLE_TICKS;
				}
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!haveBaseline || settleTicks > 0)
		{
			return;
		}
		// Task storage changes are read back too, so the stored-task baseline stays in step with every store,
		// unstore and swap.
		final boolean storage = event.getVarpId() == VarPlayerID.SLAYER_STORED_VARP
			|| event.getVarbitId() == VarbitID.SLAYER_MASTER_STORED
			|| event.getVarbitId() == VarbitID.SLAYER_TARGET_BOSSID_STORED;
		final int varp = event.getVarbitId() == -1 ? event.getVarpId() : -1;
		final boolean trigger = storage
			|| varp == VarPlayerID.SLAYER_TARGET
			|| varp == VarPlayerID.SLAYER_COUNT_ORIGINAL
			|| (varp == VarPlayerID.SLAYER_COUNT && event.getValue() > baseCount);
		if (trigger && pendingTick < 0)
		{
			pendingTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		final int now = client.getTickCount();
		if (settleTicks > 0)
		{
			if (--settleTicks == 0)
			{
				captureBaseline();
			}
		}
		else if (!haveBaseline && client.getGameState() == GameState.LOGGED_IN)
		{
			captureBaseline();
		}

		if (pendingTick >= 0 && now > pendingTick)
		{
			pendingTick = -1;
			finishAssignment(now);
		}
		if (listReadTick >= 0 && now >= listReadTick)
		{
			listReadTick = -1;
			readTaskList(now);
		}
		if (rewardsReadTick >= 0 && now >= rewardsReadTick)
		{
			rewardsReadTick = -1;
			readBlockedTasks();
		}

		final int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		skippingContext = count <= 0
			|| Boolean.TRUE.equals(currentTaskFiller)
			|| now - Math.max(lastSpeakerTick, lastMasterTick) <= CONTEXT_TICKS;
		updateLevels();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.DIALOG)
		{
			return;
		}
		// Dialogue lines arrive as "Speaker|text".
		final String message = event.getMessage();
		final int bar = message.indexOf('|');
		if (bar <= 0)
		{
			return;
		}
		final String speaker = Masters.cleanName(message.substring(0, bar));
		if (speaker != null && !isLocalPlayer(speaker))
		{
			lastSpeaker = speaker;
			lastSpeakerTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		noteMaster(event.getMenuEntry().getNpc());
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		final Actor target = event.getTarget();
		if (event.getSource() == client.getLocalPlayer() && target instanceof NPC)
		{
			noteMaster((NPC) target);
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// Rows are filled in a tick after the interface loads, so read on the next tick.
		if (event.getGroupId() == InterfaceID.SLAYER_REWARDS_TASK_LIST)
		{
			listReadTick = client.getTickCount() + 1;
		}
		else if (event.getGroupId() == InterfaceID.SLAYER_REWARDS)
		{
			rewardsReadTick = client.getTickCount() + 1;
		}
	}

	private void noteMaster(NPC npc)
	{
		if (npc == null)
		{
			return;
		}
		final String name = Masters.cleanName(npc.getName());
		if (Masters.isKnownMaster(name))
		{
			lastMaster = name;
			lastMasterTick = client.getTickCount();
		}
	}

	private void captureBaseline()
	{
		baseTarget = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		baseOriginal = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		baseCount = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		baseStored = storedTask();
		haveBaseline = true;
		pendingTick = -1;

		currentTaskFiller = baseCount > 0 ? fillerOf(baseTarget, baseOriginal) : null;
		updateLevels();
		log.debug("Slayer baseline: task {} ({}/{}), filler={}", baseTarget, baseCount, baseOriginal, currentTaskFiller);
	}

	private void finishAssignment(int now)
	{
		final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		final int original = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		final int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		final int area = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		final int slot = client.getVarbitValue(VarbitID.SLAYER_MASTER);

		final String stored = storedTask();

		final boolean changed = target != baseTarget || original != baseOriginal || count > baseCount;
		final boolean storageMoved = !stored.equals(baseStored);
		final String excluded = baseCount > 0 && baseTarget > 0 ? taskName(baseTarget) : null;
		log.debug("Task change: task {} ({}/{}), was {} ({}/{}); storage {} -> {}", target, count, original,
			baseTarget, baseCount, baseOriginal, baseStored, stored);
		baseTarget = target;
		baseOriginal = original;
		baseCount = count;
		baseStored = stored;
		if (!changed || target <= 0 || count <= 0)
		{
			return; // cancelled, cleared, completed or stored, not a new task
		}
		// A master's assignment starts at its full amount and leaves task storage alone. A task that moved through
		// storage (unstore or swap) or already has kills done is a stored task coming back, not a roll.
		if (storageMoved || count < original)
		{
			currentTaskFiller = fillerOf(target, original);
			log.debug("Task {} came out of task storage; not logged as a roll", target);
			return;
		}

		String master = null;
		if (now - lastSpeakerTick <= SPEAKER_TICKS)
		{
			master = lastSpeaker;
		}
		else if (now - lastMasterTick <= SPEAKER_TICKS)
		{
			master = lastMaster;
		}
		if (master == null)
		{
			master = store.nameForSlot(slot);
		}
		final String group = Masters.groupOf(master, slot);
		final boolean filler = Masters.isFiller(master, slot, config.fillerAya(), config.fillerTurael(), config.fillerSpria());
		final String task = taskName(target);

		store.recordRoll(RollDraft.builder()
			.timestamp(System.currentTimeMillis())
			.masterName(master != null ? master : Masters.fallbackName(slot))
			.masterSlot(slot)
			.masterGroup(group)
			.task(task)
			.taskId(target)
			.amount(original)
			.area(area)
			.filler(filler)
			.excludedTask(excluded)
			.slayerLevel(slayerLevel)
			.combatLevel(combatLevel)
			.build());
		currentTaskFiller = filler;
		log.debug("Assignment: {} x{} from {} (slot {}, group {}, filler {})", task, original, master, slot, group, filler);
	}

	private void readTaskList(int now)
	{
		final Widget drawable = client.getWidget(InterfaceID.SlayerRewardsTaskList.DRAWABLE);
		if (drawable == null)
		{
			return;
		}
		final List<String> texts = new ArrayList<>();
		collectTexts(drawable, texts, 0);
		final List<SnapshotEntry> entries = OddsParser.parse(texts);
		if (entries.size() < 3)
		{
			log.debug("Task list had {} parsable rows; ignored", entries.size());
			return;
		}

		String master = null;
		if (now - lastMasterTick <= MASTER_TICKS)
		{
			master = lastMaster;
		}
		else if (now - lastSpeakerTick <= MASTER_TICKS && Masters.isKnownMaster(lastSpeaker))
		{
			master = lastSpeaker;
		}
		if (master == null)
		{
			notice = "Couldn't tell which master that task list belongs to. Talk to the master, then open it again.";
			onNotice.run();
			return;
		}

		final int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		final String held = count > 0 ? taskName(client.getVarpValue(VarPlayerID.SLAYER_TARGET)) : null;
		updateLevels();
		final OddsSnapshot snapshot = OddsModel.buildSnapshot(Masters.groupOf(master, 0), master,
			System.currentTimeMillis(), slayerLevel, combatLevel, entries, held);
		store.addSnapshot(snapshot);
		notice = null;
		log.debug("Task list from {}: {} rows, exact weights {} (total {})", master, entries.size(),
			snapshot.isWeightsExact(), snapshot.getTotalWeight());
	}

	private void readBlockedTasks()
	{
		final Widget tasks = client.getWidget(InterfaceID.SlayerRewards.TASKS_CONTENT_SCROLLABLE);
		if (tasks == null)
		{
			return;
		}
		final List<String> texts = new ArrayList<>();
		collectTexts(tasks, texts, 0);
		final List<String> blocked = new ArrayList<>();
		boolean sawSlot = false;
		for (int i = 0; i < texts.size(); i++)
		{
			if (SLOT.matcher(texts.get(i).trim()).matches())
			{
				sawSlot = true;
				if (i + 1 < texts.size())
				{
					final String name = Masters.cleanName(texts.get(i + 1));
					if (name != null && !name.equalsIgnoreCase("Empty") && !SLOT.matcher(name).matches())
					{
						blocked.add(name);
					}
				}
			}
		}
		if (sawSlot)
		{
			store.setBlocked(blocked);
		}
	}

	private static void collectTexts(Widget w, List<String> out, int depth)
	{
		if (w == null || depth > 6)
		{
			return;
		}
		final String text = w.getText();
		if (text != null && !text.isEmpty())
		{
			out.add(text);
		}
		for (Widget[] children : new Widget[][]{w.getDynamicChildren(), w.getStaticChildren(), w.getNestedChildren()})
		{
			if (children != null)
			{
				for (Widget c : children)
				{
					collectTexts(c, out, depth + 1);
				}
			}
		}
	}

	/** Task name from the game's Slayer task table (the row whose COL_ID matches SLAYER_TARGET). */
	private String taskName(int taskId)
	{
		if (taskId <= 0)
		{
			return null;
		}
		return taskNames.computeIfAbsent(taskId, id ->
		{
			try
			{
				final List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, id);
				if (rows != null && !rows.isEmpty())
				{
					final Object[] name = client.getDBTableField(rows.get(0), DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
					if (name != null && name.length > 0 && name[0] != null)
					{
						return String.valueOf(name[0]);
					}
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Task name lookup failed for {}", id, e);
			}
			return "Task #" + id;
		});
	}

	/**
	 * What the game holds in Task Storage (Rewards > Tasks). Storing, unstoring and swapping all change it; a master's
	 * assignment doesn't.
	 */
	private String storedTask()
	{
		return client.getVarpValue(VarPlayerID.SLAYER_STORED_VARP)
			+ "/" + client.getVarbitValue(VarbitID.SLAYER_MASTER_STORED)
			+ "/" + client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID_STORED);
	}

	/** Whether a task came from a filler master: from the log when it's there, else from the master slot. */
	private Boolean fillerOf(int target, int original)
	{
		if (target <= 0)
		{
			return null;
		}
		final Boolean logged = store.fillerFor(target, original);
		if (logged != null)
		{
			return logged;
		}
		final int slot = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		return Masters.isFiller(store.nameForSlot(slot), slot, config.fillerAya(), config.fillerTurael(), config.fillerSpria());
	}

	private void updateLevels()
	{
		slayerLevel = client.getRealSkillLevel(Skill.SLAYER);
		final Player p = client.getLocalPlayer();
		if (p != null)
		{
			combatLevel = p.getCombatLevel();
		}
	}

	private boolean isLocalPlayer(String name)
	{
		final Player p = client.getLocalPlayer();
		final String own = p != null ? Masters.cleanName(p.getName()) : null;
		return own != null && own.equalsIgnoreCase(name);
	}
}

package com.slayertaskluck.tracking;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.slayertaskluck.model.OddsSnapshot;
import com.slayertaskluck.model.Roll;
import com.slayertaskluck.model.TrackerData;
import java.io.IOException;
import java.io.Reader;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Owns the tracked data for the current RuneScape profile and its JSON file. All mutations are synchronized and
 * may come from the client thread (new rolls) or the Swing thread (panel actions). Disk I/O runs on the plugin's
 * background executor, debounced, and written atomically (temp file, then move).
 */
@Slf4j
public class TrackerStore
{
	public interface DirectorySupplier
	{
		Filepath get() throws IOException;
	}

	private static final long SAVE_DELAY_MS = 1500;
	private static final long SAVE_RETRY_MS = 30_000;
	private static final String SAVE_PROBLEM = "Couldn't save data: ";

	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final DirectorySupplier directory;
	private final Runnable onChange;

	private TrackerData data = new TrackerData();
	private String profileKey;
	private boolean loaded;
	private boolean dirty;
	private String problem;
	private final List<Consumer<TrackerData>> pending = new ArrayList<>();
	private ScheduledFuture<?> saveFuture;

	public TrackerStore(Gson gson, ScheduledExecutorService executor, DirectorySupplier directory, Runnable onChange)
	{
		this.gson = gson;
		this.executor = executor;
		this.directory = directory;
		this.onChange = onChange;
	}

	// ---- profile & persistence ----

	/** Switches to another RuneScape profile: saves the current one and loads the new one in the background. */
	public void switchProfile(String key)
	{
		synchronized (this)
		{
			if (Objects.equals(key, profileKey))
			{
				return;
			}
			if (loaded && dirty)
			{
				submitSave(profileKey, data.copy());
			}
			profileKey = key;
			loaded = false;
			dirty = false;
			problem = null;
			data = new TrackerData();
			if (key != null)
			{
				final String k = key;
				execute(() -> load(k));
			}
		}
		onChange.run();
	}

	private void load(String key)
	{
		TrackerData loadedData = null;
		String loadProblem = null;
		try
		{
			final Filepath file = directory.get().joinSegment(fileName(key));
			if (file.exists())
			{
				try (Reader reader = file.openReader())
				{
					loadedData = gson.fromJson(reader, TrackerData.class);
				}
				catch (JsonParseException e)
				{
					final String aside = fileName(key) + ".unreadable-" + System.currentTimeMillis();
					file.moveTo(directory.get().joinSegment(aside), StandardCopyOption.REPLACE_EXISTING);
					loadProblem = "Saved data couldn't be read, so it was set aside as " + aside + " and tracking started fresh.";
					log.warn("Slayer Task Luck: unreadable data file moved to {}", aside, e);
				}
			}
		}
		catch (IOException e)
		{
			loadProblem = "Couldn't load saved data: " + e.getMessage();
			log.warn("Slayer Task Luck: load failed", e);
		}

		synchronized (this)
		{
			if (!key.equals(profileKey))
			{
				return; // switched again meanwhile
			}
			data = sanitize(loadedData);
			loaded = true;
			problem = loadProblem;
			if (!pending.isEmpty())
			{
				for (Consumer<TrackerData> op : pending)
				{
					op.accept(data);
				}
				pending.clear();
				markDirty();
			}
		}
		log.debug("Loaded tracker data for profile ({} rolls, {} snapshots)", data.getRolls().size(), data.getSnapshots().size());
		onChange.run();
	}

	private static TrackerData sanitize(TrackerData d)
	{
		if (d == null)
		{
			d = new TrackerData();
		}
		if (d.getSnapshots() == null)
		{
			d.setSnapshots(new ArrayList<>());
		}
		if (d.getRolls() == null)
		{
			d.setRolls(new ArrayList<>());
		}
		if (d.getWanted() == null)
		{
			d.setWanted(new HashMap<>());
		}
		if (d.getMasterNames() == null)
		{
			d.setMasterNames(new HashMap<>());
		}
		if (d.getBlocked() == null)
		{
			d.setBlocked(new ArrayList<>());
		}
		d.setSchemaVersion(TrackerData.SCHEMA_VERSION);
		return d;
	}

	/** Must be called with the lock held. */
	private void markDirty()
	{
		dirty = true;
		if (saveFuture == null || saveFuture.isDone())
		{
			try
			{
				saveFuture = executor.schedule(this::saveNow, SAVE_DELAY_MS, TimeUnit.MILLISECONDS);
			}
			catch (RejectedExecutionException e)
			{
				// shutting down; flush() handles the final save
			}
		}
	}

	private void saveNow()
	{
		final String key;
		final TrackerData snapshot;
		synchronized (this)
		{
			if (!loaded || !dirty || profileKey == null)
			{
				return;
			}
			key = profileKey;
			snapshot = data.copy(); // cheap; JSON is built outside the lock
			dirty = false;
		}
		write(key, gson.toJson(snapshot));
	}

	private void submitSave(String key, TrackerData snapshot)
	{
		execute(() -> write(key, gson.toJson(snapshot)));
	}

	private void write(String key, String json)
	{
		try
		{
			final Filepath dir = directory.get();
			// getPluginDirectory() creates .runelite/plugin-data but not this plugin's folder inside it.
			if (!dir.exists())
			{
				dir.createDirectories();
			}
			final Filepath target = dir.joinSegment(fileName(key));
			final Filepath tmp = dir.createTempFile("stl-", ".tmp");
			tmp.write(json);
			try
			{
				tmp.moveTo(target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (IOException e)
		{
			log.warn("Slayer Task Luck: save failed", e);
			synchronized (this)
			{
				if (key.equals(profileKey))
				{
					problem = SAVE_PROBLEM + e.getMessage();
					// Keep the data in memory and try again shortly.
					dirty = true;
					try
					{
						saveFuture = executor.schedule(this::saveNow, SAVE_RETRY_MS, TimeUnit.MILLISECONDS);
					}
					catch (RejectedExecutionException ignored)
					{
						// shutting down
					}
				}
			}
			onChange.run();
			return;
		}

		boolean cleared = false;
		synchronized (this)
		{
			if (key.equals(profileKey) && problem != null && problem.startsWith(SAVE_PROBLEM))
			{
				problem = null;
				cleared = true;
			}
		}
		if (cleared)
		{
			onChange.run();
		}
	}

	/** Queues a final save. Non-blocking; the executor finishes it after shutdown() is called. */
	public void flush()
	{
		synchronized (this)
		{
			if (saveFuture != null)
			{
				saveFuture.cancel(false);
				saveFuture = null;
			}
			if (loaded && dirty && profileKey != null)
			{
				submitSave(profileKey, data.copy());
				dirty = false;
			}
		}
	}

	private void execute(Runnable r)
	{
		try
		{
			executor.execute(r);
		}
		catch (RejectedExecutionException e)
		{
			log.debug("executor stopped; dropping task");
		}
	}

	static String fileName(String profileKey)
	{
		return profileKey.replaceAll("[^A-Za-z0-9_-]", "_") + ".json";
	}

	// ---- reads ----

	public synchronized boolean isLoaded()
	{
		return loaded;
	}

	public synchronized boolean hasProfile()
	{
		return profileKey != null;
	}

	public synchronized String getProblem()
	{
		return problem;
	}

	/** Copy for background computation (view building, export). Holds the lock only for a field copy. */
	public synchronized TrackerData copy()
	{
		return data.copy();
	}

	/** Whether the most recent roll with this task and amount came from a filler master, or null if unknown. */
	public synchronized Boolean fillerFor(int taskId, int amount)
	{
		final List<Roll> rolls = data.getRolls();
		for (int i = rolls.size() - 1; i >= 0; i--)
		{
			final Roll r = rolls.get(i);
			if (r.getTaskId() == taskId && r.getAmount() == amount)
			{
				return r.isFiller();
			}
		}
		return null;
	}

	// ---- mutations ----

	private void mutate(Consumer<TrackerData> op)
	{
		synchronized (this)
		{
			if (!loaded)
			{
				if (profileKey != null)
				{
					pending.add(op);
				}
				return;
			}
			op.accept(data);
			markDirty();
		}
		onChange.run();
	}

	public void addSnapshot(OddsSnapshot s)
	{
		mutate(d ->
		{
			d.getMasterNames().put(s.getMasterGroup(), s.getMasterName());
			for (OddsSnapshot existing : RollScorer.snapshotsNewestFirst(d, s.getMasterGroup()))
			{
				if (Objects.equals(existing.getContentHash(), s.getContentHash()))
				{
					return; // unchanged list; keep the original (rolls since then already use it)
				}
				break;
			}
			d.getSnapshots().add(s);
		});
	}

	public void recordRoll(RollDraft draft)
	{
		mutate(d ->
		{
			if (draft.getMasterName() != null)
			{
				d.getMasterNames().put(draft.getMasterGroup(), draft.getMasterName());
				d.getMasterNames().put(slotKey(draft.getMasterSlot()), draft.getMasterName());
			}
			d.getRolls().add(RollScorer.build(d, draft));
		});
	}

	/** Last master name seen for a role slot, used when an assignment arrives without a dialogue line. */
	public synchronized String nameForSlot(int slot)
	{
		return data.getMasterNames().get(slotKey(slot));
	}

	private static String slotKey(int slot)
	{
		return "#slot" + slot;
	}

	public void setWanted(String group, Collection<String> tasks)
	{
		mutate(d -> d.getWanted().put(group, new ArrayList<>(new LinkedHashSet<>(tasks))));
	}

	public void setExcluded(String rollId, boolean excluded)
	{
		mutate(d ->
		{
			for (Roll r : d.getRolls())
			{
				if (r.getId().equals(rollId))
				{
					r.setExcluded(excluded);
				}
			}
		});
	}

	/** Re-scores every target roll of a group with the current wanted tasks. */
	public void rescore(String group)
	{
		mutate(d ->
		{
			for (Roll r : d.getRolls())
			{
				if (!r.isFiller() && group.equals(r.getMasterGroup()))
				{
					RollScorer.score(d, r);
				}
			}
		});
	}

	public void setBlocked(List<String> blocked)
	{
		mutate(d ->
		{
			final boolean seenBefore = d.getBlockedChangedAt() != 0;
			if (!seenBefore)
			{
				// The first read is a baseline, not a change (1 = "seen, never changed").
				d.setBlocked(new ArrayList<>(blocked));
				d.setBlockedChangedAt(1);
			}
			else if (!new LinkedHashSet<>(d.getBlocked()).equals(new LinkedHashSet<>(blocked)))
			{
				d.setBlocked(new ArrayList<>(blocked));
				d.setBlockedChangedAt(System.currentTimeMillis());
			}
		});
	}

	public void reset()
	{
		mutate(d ->
		{
			d.getRolls().clear();
			d.getSnapshots().clear();
			d.getWanted().clear();
			d.getMasterNames().clear();
			d.getBlocked().clear();
			d.setBlockedChangedAt(0);
		});
	}
}

package com.slayertaskluck.tracking;

/**
 * Recovers the game's integer task weights from the task list's percentages.
 *
 * <p>The game shows each chance as {@code floor(1000 * w / W) / 10} percent (truncated, not rounded), which is why
 * the list sums to about 98-99%. For a total weight {@code W < 1000} each shown value pins its weight to at most one
 * integer, so the smallest {@code W} for which every row has a valid weight and the weights add up to {@code W}
 * gives the exact weights. Kuradal's list, for example, resolves to a total of 161.
 */
public final class WeightInference
{
	/** Above this the per-row intervals can hold more than one integer and the answer stops being unique. */
	private static final int MAX_TOTAL = 999;

	private WeightInference()
	{
	}

	/**
	 * @param permille shown percentages in tenths of a percent (0 = unavailable)
	 * @return integer weights in the same order (0 where unavailable), or null when no exact fit exists
	 */
	public static int[] infer(int[] permille)
	{
		int available = 0;
		for (int s : permille)
		{
			if (s < 0 || s > 1000)
			{
				return null;
			}
			if (s > 0)
			{
				available++;
			}
		}
		if (available == 0)
		{
			return null;
		}

		final int[] weights = new int[permille.length];
		for (int total = available; total <= MAX_TOTAL; total++)
		{
			long sum = 0;
			boolean feasible = true;
			for (int i = 0; i < permille.length && feasible; i++)
			{
				final int s = permille[i];
				if (s == 0)
				{
					weights[i] = 0;
					continue;
				}
				// floor(1000 w / total) == s  <=>  s * total / 1000 <= w < (s + 1) * total / 1000
				final long lo = ceilDiv((long) s * total, 1000);
				final long hi = ceilDiv((long) (s + 1) * total, 1000) - 1;
				if (lo < 1 || lo > hi)
				{
					feasible = false;
				}
				else
				{
					weights[i] = (int) lo;
					sum += lo;
				}
			}
			if (feasible && sum == total && matches(permille, weights, total))
			{
				return weights.clone();
			}
		}
		return null;
	}

	/** True when these weights reproduce every shown value exactly. */
	public static boolean matches(int[] permille, int[] weights, int total)
	{
		for (int i = 0; i < permille.length; i++)
		{
			if (weights[i] == 0)
			{
				if (permille[i] != 0)
				{
					return false;
				}
				continue;
			}
			if ((int) ((1000L * weights[i]) / total) != permille[i])
			{
				return false;
			}
		}
		return true;
	}

	private static long ceilDiv(long a, long b)
	{
		return -Math.floorDiv(-a, b);
	}
}

package com.slayertaskluck.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/** A titled section that opens and closes on click. Only "Luck over time" starts open. */
class CollapsibleSection extends JPanel
{
	private static final int BAR_PADDING = 8;

	private final String title;
	private final JLabel header = new JLabel();
	private final JLabel summary = new JLabel();
	private final JPanel content = new JPanel();
	private String summaryText = "";
	private boolean open;

	CollapsibleSection(String title, boolean open)
	{
		this.title = title;
		this.open = open;
		setLayout(new BorderLayout());
		setBackground(UiStyle.BACKGROUND);
		setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));
		setAlignmentX(Component.LEFT_ALIGNMENT);

		final JPanel bar = new JPanel(new BorderLayout());
		bar.setBackground(UiStyle.CARD);
		bar.setBorder(BorderFactory.createEmptyBorder(5, BAR_PADDING, 5, BAR_PADDING));
		bar.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		header.setFont(FontManager.getRunescapeBoldFont());
		header.setForeground(UiStyle.TEXT);
		summary.setFont(FontManager.getRunescapeSmallFont());
		summary.setForeground(UiStyle.MUTED);
		bar.add(header, BorderLayout.WEST);
		bar.add(summary, BorderLayout.EAST);
		bar.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				setOpen(!CollapsibleSection.this.open);
			}
		});

		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(UiStyle.BACKGROUND);
		content.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));

		add(bar, BorderLayout.NORTH);
		add(content, BorderLayout.CENTER);
		setOpen(open);
	}

	JPanel content()
	{
		return content;
	}

	/** Short text on the right of the header, visible even while collapsed. Shortened with "..." if it won't fit. */
	void setSummary(String text)
	{
		summaryText = text == null ? "" : text;
		fitSummary();
	}

	private void fitSummary()
	{
		final int room = UiStyle.CONTENT_WIDTH - BAR_PADDING * 2 - header.getPreferredSize().width - UiStyle.ROW_GAP;
		summary.setText(UiStyle.fit(summaryText, summary.getFontMetrics(summary.getFont()), room));
	}

	void setOpen(boolean open)
	{
		this.open = open;
		header.setText((open ? "- " : "+ ") + title);
		fitSummary();
		content.setVisible(open);
		revalidate();
		repaint();
	}
}

package com.slayertaskluck.ui;

import com.slayertaskluck.math.Verdict;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/**
 * Lifetime luck as a position on a bar: far left is unluckiest, far right luckiest. The shaded ends are the rarest
 * results on each side (the configured thresholds); the dot is the player.
 */
class LuckBar extends JComponent
{
	private static final int BAR_HEIGHT = 8;
	private static final int DOT = 12;

	private double percentile = Double.NaN;
	private Verdict.Tone tone = Verdict.Tone.NONE;
	private double unluckyCut = 0.1;
	private double luckyCut = 0.1;

	LuckBar()
	{
		setPreferredSize(new Dimension(UiStyle.CONTENT_WIDTH, 34));
		setMinimumSize(getPreferredSize());
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
	}

	void setValue(double percentile, Verdict.Tone tone, double unluckyCut, double luckyCut)
	{
		this.percentile = percentile;
		this.tone = tone;
		this.unluckyCut = unluckyCut;
		this.luckyCut = luckyCut;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g0)
	{
		final Graphics2D g = (Graphics2D) g0.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		final int pad = DOT / 2;
		final int w = getWidth() - 2 * pad;
		final int y = 4;

		g.setColor(UiStyle.blend(UiStyle.CARD, Color.WHITE, 0.08));
		g.fillRoundRect(pad, y + 2, w, BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);
		g.setColor(UiStyle.blend(UiStyle.CARD, UiStyle.UNLUCKY, 0.45));
		g.fillRoundRect(pad, y + 2, (int) Math.round(w * unluckyCut) + BAR_HEIGHT / 2, BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);
		g.setColor(UiStyle.blend(UiStyle.CARD, UiStyle.LUCKY, 0.45));
		final int luckyW = (int) Math.round(w * luckyCut);
		g.fillRoundRect(pad + w - luckyW - BAR_HEIGHT / 2, y + 2, luckyW + BAR_HEIGHT / 2, BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);

		if (!Double.isNaN(percentile))
		{
			final int x = pad + (int) Math.round(w * Math.max(0, Math.min(1, percentile)));
			g.setColor(UiStyle.CARD);
			g.fillOval(x - DOT / 2 - 1, y + 2 + BAR_HEIGHT / 2 - DOT / 2 - 1, DOT + 2, DOT + 2);
			g.setColor(tone == Verdict.Tone.NORMAL ? Color.WHITE : UiStyle.toneColor(tone));
			g.fillOval(x - DOT / 2, y + 2 + BAR_HEIGHT / 2 - DOT / 2, DOT, DOT);
		}

		g.setFont(FontManager.getRunescapeSmallFont());
		g.setColor(UiStyle.MUTED);
		final int textY = y + BAR_HEIGHT + 20;
		g.drawString("unluckiest", pad, textY);
		final String right = "luckiest";
		g.drawString(right, pad + w - g.getFontMetrics().stringWidth(right), textY);
		g.dispose();
	}
}

package com.slayertaskluck.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/**
 * Luck over time: wanted tasks received minus expected after each roll. The dashed line is "exactly as expected";
 * the shaded bands are normal ups and downs (1 and 2 standard deviations). A line sinking below the band means
 * sustained bad luck.
 */
class LuckChart extends JComponent
{
	private static final int HEIGHT = 120;
	private static final int PAD_X = 4;
	private static final int PAD_Y = 8;

	private double[] diff = new double[0];
	private double[] sd = new double[0];

	LuckChart()
	{
		setPreferredSize(new Dimension(UiStyle.CONTENT_WIDTH, HEIGHT));
		setMinimumSize(getPreferredSize());
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		setToolTipText("");
	}

	void setData(double[] diff, double[] sd)
	{
		this.diff = diff;
		this.sd = sd;
		repaint();
	}

	private double range()
	{
		double max = 1;
		for (int i = 0; i < diff.length; i++)
		{
			max = Math.max(max, Math.max(Math.abs(diff[i]), 2.2 * sd[i]));
		}
		return max * 1.1;
	}

	private int x(int i, int w)
	{
		final int n = Math.max(1, diff.length);
		return PAD_X + (int) Math.round((w - 2 * PAD_X) * (i + 1) / (double) n);
	}

	private int y(double v, double range, int h)
	{
		final double mid = h / 2.0;
		return (int) Math.round(mid - v / range * (mid - PAD_Y));
	}

	@Override
	protected void paintComponent(Graphics g0)
	{
		final Graphics2D g = (Graphics2D) g0.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		final int w = getWidth();
		final int h = getHeight();
		g.setColor(UiStyle.CARD);
		g.fillRect(0, 0, w, h);

		final int n = diff.length;
		if (n == 0)
		{
			g.dispose();
			return;
		}
		final double range = range();

		band(g, 2, range, w, h, UiStyle.blend(UiStyle.CARD, Color.WHITE, 0.05));
		band(g, 1, range, w, h, UiStyle.blend(UiStyle.CARD, Color.WHITE, 0.10));

		g.setColor(UiStyle.MUTED);
		g.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f, new float[]{4f, 4f}, 0f));
		g.drawLine(PAD_X, y(0, range, h), w - PAD_X, y(0, range, h));

		final double last = diff[n - 1];
		final double lastSd = sd[n - 1];
		g.setColor(last < -lastSd ? UiStyle.UNLUCKY : last > lastSd ? UiStyle.LUCKY : Color.WHITE);
		g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		int px = PAD_X;
		int py = y(0, range, h);
		for (int i = 0; i < n; i++)
		{
			final int cx = x(i, w);
			final int cy = y(diff[i], range, h);
			g.drawLine(px, py, cx, cy);
			px = cx;
			py = cy;
		}

		g.setFont(FontManager.getRunescapeSmallFont());
		g.setColor(UiStyle.MUTED);
		g.drawString(n + " rolls", w - PAD_X - g.getFontMetrics().stringWidth(n + " rolls"), h - 3);
		g.dispose();
	}

	private void band(Graphics2D g, double k, double range, int w, int h, Color color)
	{
		final int n = diff.length;
		final Polygon p = new Polygon();
		p.addPoint(PAD_X, y(0, range, h));
		for (int i = 0; i < n; i++)
		{
			p.addPoint(x(i, w), y(k * sd[i], range, h));
		}
		for (int i = n - 1; i >= 0; i--)
		{
			p.addPoint(x(i, w), y(-k * sd[i], range, h));
		}
		g.setColor(color);
		g.fillPolygon(p);
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		final int n = diff.length;
		if (n == 0)
		{
			return null;
		}
		final int w = getWidth();
		int best = 0;
		for (int i = 0; i < n; i++)
		{
			if (Math.abs(x(i, w) - e.getX()) < Math.abs(x(best, w) - e.getX()))
			{
				best = i;
			}
		}
		final double d = diff[best];
		return "After roll " + (best + 1) + ": " + (d >= 0 ? "+" : "") + UiStyle.oneDecimal(d)
			+ " wanted vs expected (normal range ±" + UiStyle.oneDecimal(sd[best]) + ")";
	}
}

