package com.slayertaskluck.tracking;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.slayertaskluck.model.OddsSnapshot;
import com.slayertaskluck.model.SnapshotEntry;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class OddsParsingTest
{
	@Test
	public void parsesRowsIncludingTagsAndVaries()
	{
		final List<SnapshotEntry> rows = OddsParser.parse(Arrays.asList(
			"Slayer Tasks", "Araxytes (60-80)", "", "0.0%", "Boss (Varies)", "0.0%",
			"<col=ff9040>Gargoyles (130-200)</col>", "4.9%", "stray 1.0%"));
		assertEquals(3, rows.size());
		assertEquals("Araxytes", rows.get(0).getName());
		assertEquals(60, rows.get(0).getMin());
		assertEquals(80, rows.get(0).getMax());
		assertEquals("Boss", rows.get(1).getName());
		assertEquals(0, rows.get(1).getMax());
		assertEquals("Gargoyles", rows.get(2).getName());
		assertEquals(4.9, rows.get(2).getShownPercent(), 1e-9);
	}

	@Test
	public void parsesFullKuradalList()
	{
		assertEquals(43, OddsParser.parse(KuradalFixture.texts(KuradalFixture.NO_TASK)).size());
	}

	@Test
	public void recoversExactWeightsFromTruncatedPercentages()
	{
		final OddsSnapshot s = snapshot(KuradalFixture.NO_TASK, null);
		assertTrue(s.isWeightsExact());
		assertEquals(161, s.getTotalWeight());
		for (SnapshotEntry e : s.getEntries())
		{
			assertEquals(e.getName(), KuradalFixture.expectedWeight(e.getName()), e.getWeight());
		}
	}

	@Test
	public void currentTaskShowsAsZeroAndRescalesTheRest()
	{
		final OddsSnapshot s = snapshot(KuradalFixture.ON_FIRE_GIANTS, "Fire Giants");
		assertTrue(s.isWeightsExact());
		assertEquals(154, s.getTotalWeight());
		assertEquals("Fire Giants", s.getHeldTask());
		assertEquals(8, OddsModel.find(s, "Gargoyles").getWeight());
	}

	@Test
	public void heldTaskWeightIsBorrowedFromAnotherSnapshot()
	{
		final OddsSnapshot full = snapshot(KuradalFixture.NO_TASK, null);
		final OddsSnapshot held = snapshot(KuradalFixture.ON_FIRE_GIANTS, "Fire Giants");
		final Map<String, Integer> borrowed = OddsModel.learnedWeights(Arrays.asList(held, full));

		assertFalse(OddsModel.missingHeldWeight(held, null, borrowed));
		final Map<String, Double> dist = OddsModel.distribution(held, null, borrowed);
		assertEquals(7 / 161.0, dist.get("Fire Giants"), 1e-12);
		assertEquals(8 / 161.0, dist.get("Gargoyles"), 1e-12);
		assertTrue(OddsModel.missingHeldWeight(held, null, Collections.emptyMap()));
	}

	@Test
	public void activeTaskIsLeftOutOfTheRoll()
	{
		final OddsSnapshot full = snapshot(KuradalFixture.NO_TASK, null);
		final Map<String, Double> dist = OddsModel.distribution(full, "Gargoyles", null);
		assertNull(dist.get("Gargoyles"));
		assertEquals(12 / 153.0, dist.get("Abyssal Demons"), 1e-12);
	}

	@Test
	public void scoresWantedAndBossFallback()
	{
		final OddsSnapshot full = snapshot(KuradalFixture.NO_TASK, null);
		final Map<String, Double> dist = OddsModel.distribution(full, null, null);

		final OddsModel.Scored hit = OddsModel.score(dist, "Abyssal Demons", Arrays.asList("abyssal demons", "Dark Beasts", "Dark Beasts"));
		assertEquals("Abyssal Demons", hit.getMatched());
		assertTrue(hit.isWanted());
		assertEquals(23 / 161.0, hit.getPWanted(), 1e-12);

		final OddsModel.Scored miss = OddsModel.score(dist, "Kalphite", Collections.singletonList("Dark Beasts"));
		assertNull("Kalphites is blocked (0%), so it can't match", miss.getMatched());

		final OddsModel.Scored gargoyles = OddsModel.score(dist, "Gargoyles", Collections.singletonList("Dark Beasts"));
		assertNotNull(gargoyles.getMatched());
		assertFalse(gargoyles.isWanted());
	}

	@Test
	public void identicalListsHashTheSame()
	{
		assertEquals(snapshot(KuradalFixture.NO_TASK, null).getContentHash(), snapshot(KuradalFixture.NO_TASK, null).getContentHash());
		assertFalse(snapshot(KuradalFixture.NO_TASK, null).getContentHash()
			.equals(snapshot(KuradalFixture.ON_FIRE_GIANTS, "Fire Giants").getContentHash()));
	}

	@Test
	public void weightInferenceRejectsImpossibleLists()
	{
		assertNull(WeightInference.infer(new int[]{0, 0}));
		assertNull(WeightInference.infer(new int[]{999, 999}));
	}

	@Test
	public void mastersGroupAndFillers()
	{
		assertEquals("duradel", Masters.groupOf("Kuradal", 5));
		assertEquals("duradel", Masters.groupOf("Duradel", 5));
		assertEquals("turael", Masters.groupOf("Aya", 1));
		assertEquals("slot5", Masters.groupOf(null, 5));
		assertTrue(Masters.isFiller("Aya", 1, true, false, false));
		assertFalse(Masters.isFiller("Turael", 1, true, false, false));
		assertFalse(Masters.isFiller("Kuradal", 5, true, true, true));
		assertTrue(Masters.isFiller(null, 1, true, false, false));
		assertEquals("Some Player", Masters.cleanName("<col=ffffff>Some Player</col>"));
	}

	static OddsSnapshot snapshot(String[][] rows, String held)
	{
		return OddsModel.buildSnapshot("duradel", "Kuradal", 1000, 90, 120,
			OddsParser.parse(KuradalFixture.texts(rows)), held);
	}
}

package com.slayertaskluck.tracking;

import com.google.gson.Gson;
import com.slayertaskluck.SlayerTaskLuckConfig;
import com.slayertaskluck.math.FairnessCache;
import com.slayertaskluck.math.StatsCalculator;
import com.slayertaskluck.model.OddsSnapshot;
import com.slayertaskluck.model.TrackerData;
import com.slayertaskluck.ui.SlayerTaskLuckOverlay;
import com.slayertaskluck.ui.SlayerTaskLuckPanel;
import com.slayertaskluck.ui.PanelActions;
import com.slayertaskluck.ui.TrackerView;
import com.slayertaskluck.ui.ViewBuilder;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Random;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.LongSupplier;
import javax.swing.SwingUtilities;
import org.junit.Assume;
import org.junit.Test;

/**
 * Timing check for the plugin's heavier paths at large history sizes. Skipped in normal builds; run with
 * {@code STL_PERF=1 ./gradlew test --tests '*PerformanceBenchmark' --rerun-tasks}. Writes build/perf-report.txt.
 */
public class PerformanceBenchmark
{
	private static final int[] SIZES = {100, 1_000, 5_000, 20_000};

	@Test
	public void benchmark() throws Exception
	{
		Assume.assumeTrue("set STL_PERF=1 to run", "1".equals(System.getenv("STL_PERF")));
		final Gson gson = new Gson();
		final StringBuilder out = new StringBuilder();
		out.append("Slayer Task Luck performance check (median of 5 runs after warm-up)\n");
		out.append("Budgets: one frame at 50 fps = 20 ms, one game tick = 600 ms\n\n");

		final List<String> listTexts = KuradalFixture.texts(KuradalFixture.NO_TASK);
		line(out, "Read a task list (parse + weight recovery), client thread", micros(() ->
		{
			OddsModel.buildSnapshot("duradel", "Kuradal", 1, 90, 120, OddsParser.parse(listTexts), null);
			return 0;
		}), "us");

		for (int n : SIZES)
		{
			final TrackerData data = history(n);
			final String json = gson.toJson(data);
			out.append(String.format(Locale.ROOT, "%n== %,d Kuradal rolls + %,d Aya skips (save file %,d KB) ==%n", n, n, json.length() / 1024));

			line(out, "Log a new task (scoring, under the data lock), client thread", micros(() ->
			{
				RollScorer.build(data, draft(n * 2L + 5, "Gargoyles", false));
				return 0;
			}), "us");
			line(out, "Copy data for the background thread (data lock held)", millis(() -> data.copy().getRolls().size()), "ms");
			line(out, "Serialize a save (background thread, no lock)", millis(() -> gson.toJson(data.copy()).length()), "ms");
			line(out, "Stats without fairness, background thread", millis(() ->
				StatsCalculator.compute(data, "duradel", "Kuradal", 0.1, 0.1, false).getRolls()), "ms");
			line(out, "Stats with fairness simulation, background thread", millis(() ->
				StatsCalculator.compute(data, "duradel", "Kuradal", 0.1, 0.1, true).getRolls()), "ms");

			final TrackerView view = ViewBuilder.build(data, TrackerView.State.READY, null, null, 0.1, 0.1,
				name -> "Aya".equals(name), 90, 120, null);
			final FairnessCache cache = new FairnessCache();
			line(out, "View rebuild after a new roll (fairness re-run), background", millis(() ->
				ViewBuilder.build(data, TrackerView.State.READY, null, null, 0.1, 0.1, name -> "Aya".equals(name), 90, 120, null).getRollCount()), "ms");
			ViewBuilder.build(data, TrackerView.State.READY, null, null, 0.1, 0.1, name -> "Aya".equals(name), 90, 120, cache);
			line(out, "View rebuild after ticking a wanted task (fairness cached)", millis(() ->
				ViewBuilder.build(data, TrackerView.State.READY, null, null, 0.1, 0.1, name -> "Aya".equals(name), 90, 120, cache).getRollCount()), "ms");
			line(out, "Side panel refresh, Swing thread", millis(() -> panelUpdate(view)), "ms");
			line(out, "Overlay draw, every frame", overlayMicros(view), "us");
		}

		final String report = out.toString();
		System.out.println(report);
		Files.createDirectories(Paths.get("build"));
		Files.write(Paths.get("build", "perf-report.txt"), report.getBytes(StandardCharsets.UTF_8));
	}

	/** A long, realistic Turael-skip history: each Kuradal roll is followed by an Aya skip. */
	private static TrackerData history(int targetRolls)
	{
		final TrackerData d = new TrackerData();
		final OddsSnapshot snap = OddsModel.buildSnapshot("duradel", "Kuradal", 0, 90, 120,
			OddsParser.parse(KuradalFixture.texts(KuradalFixture.NO_TASK)), null);
		d.getSnapshots().add(snap);
		d.getWanted().put("duradel", Arrays.asList("Abyssal Demons", "Dark Beasts"));
		final Map<String, Double> dist = OddsModel.distribution(snap, null, null);
		final String[] tasks = dist.keySet().toArray(new String[0]);
		final double[] cum = new double[tasks.length];
		double run = 0;
		for (int i = 0; i < tasks.length; i++)
		{
			run += dist.get(tasks[i]);
			cum[i] = run;
		}
		final Random random = new Random(42);
		for (int i = 0; i < targetRolls; i++)
		{
			final double u = random.nextDouble();
			int t = 0;
			while (t < tasks.length - 1 && cum[t] < u)
			{
				t++;
			}
			d.getRolls().add(RollScorer.build(d, draft(i * 2L + 1, tasks[t], false)));
			d.getRolls().add(RollScorer.build(d, draft(i * 2L + 2, "Crawling Hands", true)));
		}
		return d;
	}

	private static RollDraft draft(long step, String task, boolean filler)
	{
		return RollDraft.builder()
			.timestamp(1_000_000L + step * 300_000L)
			.masterName(filler ? "Aya" : "Kuradal")
			.masterSlot(filler ? 1 : 5)
			.masterGroup(filler ? "turael" : "duradel")
			.task(task)
			.amount(150)
			.filler(filler)
			.slayerLevel(90)
			.combatLevel(120)
			.build();
	}

	private static int panelUpdate(TrackerView view)
	{
		final AtomicReference<RuntimeException> error = new AtomicReference<>();
		try
		{
			SwingUtilities.invokeAndWait(() ->
			{
				try
				{
					PANEL.get().update(view, 0.1, 0.1);
				}
				catch (RuntimeException e)
				{
					error.set(e);
				}
			});
		}
		catch (Exception e)
		{
			throw new IllegalStateException(e);
		}
		if (error.get() != null)
		{
			throw error.get();
		}
		return 0;
	}

	private static final ThreadLocal<SlayerTaskLuckPanel> PANEL_HOLDER = new ThreadLocal<>();
	private static final java.util.function.Supplier<SlayerTaskLuckPanel> PANEL = () ->
	{
		if (PANEL_HOLDER.get() == null)
		{
			PANEL_HOLDER.set(new SlayerTaskLuckPanel(new PanelActions()
			{
				@Override
				public void setWanted(String group, List<String> tasks)
				{
				}

				@Override
				public void setExcluded(String rollId, boolean excluded)
				{
				}

				@Override
				public void rescore(String group)
				{
				}

				@Override
				public void resetData()
				{
				}

				@Override
				public void exportCsv()
				{
				}
			}));
		}
		return PANEL_HOLDER.get();
	};

	private static double overlayMicros(TrackerView view)
	{
		final SlayerTaskLuckConfig config = new SlayerTaskLuckConfig()
		{
		};
		final SlayerTaskLuckOverlay overlay = new SlayerTaskLuckOverlay(config, () -> view, () -> true);
		final BufferedImage image = new BufferedImage(800, 600, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		final int frames = 20_000;
		for (int i = 0; i < frames; i++)
		{
			overlay.render(g); // warm-up
		}
		final long start = System.nanoTime();
		for (int i = 0; i < frames; i++)
		{
			overlay.render(g);
		}
		final double us = (System.nanoTime() - start) / 1000.0 / frames;
		g.dispose();
		return us;
	}

	private static double micros(LongSupplier work)
	{
		return median(work, 200) / 1000.0;
	}

	private static double millis(LongSupplier work)
	{
		return median(work, 1) / 1_000_000.0;
	}

	/** Median wall time in ns of one call (averaged over `inner` calls per sample). */
	private static double median(LongSupplier work, int inner)
	{
		for (int i = 0; i < 3; i++)
		{
			for (int j = 0; j < inner; j++)
			{
				work.getAsLong();
			}
		}
		final double[] samples = new double[5];
		for (int s = 0; s < samples.length; s++)
		{
			final long start = System.nanoTime();
			for (int j = 0; j < inner; j++)
			{
				work.getAsLong();
			}
			samples[s] = (System.nanoTime() - start) / (double) inner;
		}
		Arrays.sort(samples);
		return samples[samples.length / 2];
	}

	private static void line(StringBuilder out, String what, double value, String unit)
	{
		out.append(String.format(Locale.ROOT, "  %-62s %10.2f %s%n", what, value, unit));
	}
}

package com.slayertaskluck.tracking;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.slayertaskluck.math.FairnessCache;
import com.slayertaskluck.math.GroupStats;
import com.slayertaskluck.math.StatsCalculator;
import com.slayertaskluck.math.Verdict;
import com.slayertaskluck.model.Confidence;
import com.slayertaskluck.model.OddsSnapshot;
import com.slayertaskluck.model.Roll;
import com.slayertaskluck.model.TrackerData;
import com.slayertaskluck.ui.TrackerView;
import com.slayertaskluck.ui.ViewBuilder;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/** Replays a Turael-skip session through scoring and stats and checks the numbers shown. */
public class ReplayTest
{
	private static final long MIN = 60_000L;
	private static final double WANTED_P = 23 / 161.0; // Abyssal Demons (12) + Dark Beasts (11)

	private static TrackerData session()
	{
		final TrackerData d = new TrackerData();
		d.getSnapshots().add(OddsParsingTest.snapshot(KuradalFixture.NO_TASK, null)); // timestamp 1000
		d.getWanted().put("duradel", Arrays.asList("Abyssal Demons", "Dark Beasts"));

		add(d, 1 * MIN, "Kuradal", "Gargoyles", false);
		add(d, 2 * MIN, "Aya", "Crawling Hands", true);
		add(d, 11 * MIN, "Kuradal", "Trolls", false);
		add(d, 12 * MIN, "Aya", "Cows", true);
		add(d, 21 * MIN, "Kuradal", "Abyssal Demons", false);
		add(d, 60 * MIN, "Kuradal", "Gargoyles", false);
		add(d, 61 * MIN, "Aya", "Rats", true);
		add(d, 70 * MIN, "Kuradal", "Kalphite", false); // blocked: not on the list -> NONE
		return d;
	}

	private static void add(TrackerData d, long t, String master, String task, boolean filler)
	{
		d.getRolls().add(RollScorer.build(d, RollDraft.builder()
			.timestamp(t)
			.masterName(master)
			.masterSlot(filler ? 1 : 5)
			.masterGroup(Masters.groupOf(master, filler ? 1 : 5))
			.task(task)
			.amount(100)
			.filler(filler)
			.slayerLevel(90)
			.combatLevel(120)
			.build()));
	}

	@Test
	public void scoresEachRollFromTheSnapshot()
	{
		final TrackerData d = session();
		final Roll first = d.getRolls().get(0);
		assertEquals(Confidence.CURRENT, first.getConfidence());
		assertEquals(8 / 161.0, first.getPTask(), 1e-12);
		assertEquals(WANTED_P, first.getPWanted(), 1e-12);
		assertFalse(first.getWanted());

		final Roll filler = d.getRolls().get(1);
		assertTrue(filler.isFiller());
		assertNull(filler.getPWanted());

		assertTrue(d.getRolls().get(4).getWanted());
		assertEquals(Confidence.NONE, d.getRolls().get(7).getConfidence());
	}

	@Test
	public void statsMatchTheSession()
	{
		final GroupStats s = StatsCalculator.compute(session(), "duradel", "Kuradal", 0.1, 0.1, true);
		assertEquals(4, s.getRolls());
		assertEquals(1, s.getUncounted());
		assertEquals(1, s.getObserved());
		assertEquals(4 * WANTED_P, s.getExpected(), 1e-12);
		assertEquals(1, s.getDryRolls());
		assertEquals(1 - WANTED_P, s.getDryProbability(), 1e-12);
		assertEquals(Verdict.Tone.NORMAL, s.getDryVerdict().getTone());
		assertEquals(2, s.getLongestDry());
		// One filler since the last wanted roll, timed until the next assignment (9 minutes).
		assertEquals(1, s.getDetours());
		assertEquals(9 * MIN, s.getDetourMillis());
		assertEquals(3, s.getTotalDetours());
		assertEquals(4, s.getChartDiff().length);
		assertEquals(1 - 4 * WANTED_P, s.getChartDiff()[3], 1e-12);
		assertEquals(WANTED_P, s.getChancePerRoll(), 1e-12);
		assertNull("fairness waits for 50 rolls", s.getFairness());
	}

	@Test
	public void excludingARollTakesItOutOfTheStats()
	{
		final TrackerData d = session();
		d.getRolls().get(4).setExcluded(true); // the wanted Abyssal Demons roll
		final GroupStats s = StatsCalculator.compute(d, "duradel", "Kuradal", 0.1, 0.1, false);
		assertEquals(3, s.getRolls());
		assertEquals(0, s.getObserved());
		assertEquals(3, s.getDryRolls());
	}

	@Test
	public void rescoringAppliesANewWantedList()
	{
		final TrackerData d = session();
		d.getWanted().put("duradel", Arrays.asList("Gargoyles"));
		for (Roll r : d.getRolls())
		{
			if (!r.isFiller())
			{
				RollScorer.score(d, r);
			}
		}
		final GroupStats s = StatsCalculator.compute(d, "duradel", "Kuradal", 0.1, 0.1, false);
		assertEquals(2, s.getObserved());
		assertEquals(4 * 8 / 161.0, s.getExpected(), 1e-12);
	}

	@Test
	public void copyIsEqualButIndependent()
	{
		final TrackerData d = session();
		final TrackerData c = d.copy();
		assertEquals(d, c);
		c.getRolls().get(0).setExcluded(true);
		c.getWanted().get("duradel").add("Trolls");
		assertFalse(d.getRolls().get(0).isExcluded());
		assertFalse(d.getWanted().get("duradel").contains("Trolls"));
	}

	@Test
	public void fairnessIsReusedUntilTheCountedRollsChange()
	{
		final TrackerData d = new TrackerData();
		d.getSnapshots().add(OddsParsingTest.snapshot(KuradalFixture.NO_TASK, null));
		d.getWanted().put("duradel", new java.util.ArrayList<>(Arrays.asList("Abyssal Demons")));
		for (int i = 0; i < 55; i++)
		{
			add(d, 2000 + i * MIN, "Kuradal", i % 2 == 0 ? "Gargoyles" : "Trolls", false);
		}
		final FairnessCache cache = new FairnessCache();
		final GroupStats first = StatsCalculator.compute(d, "duradel", "Kuradal", 0.1, 0.1, true, cache);
		d.getWanted().put("duradel", Arrays.asList("Trolls")); // wanted list doesn't affect fairness
		final GroupStats again = StatsCalculator.compute(d, "duradel", "Kuradal", 0.1, 0.1, true, cache);
		assertSame(first.getFairness(), again.getFairness());

		add(d, 900 * MIN, "Kuradal", "Drakes", false);
		final GroupStats after = StatsCalculator.compute(d, "duradel", "Kuradal", 0.1, 0.1, true, cache);
		assertEquals(56, after.getFairness().getRolls());
	}

	@Test
	public void pickerListsEveryTargetMasterUsedOnesFirst()
	{
		final TrackerData d = session();
		d.getMasterNames().put("duradel", "Kuradal"); // the store records the name last seen
		final TrackerView v = view(d);
		final List<String> names = new ArrayList<>();
		for (TrackerView.MasterOption o : v.getMasters())
		{
			names.add(o.getName());
		}
		assertEquals("Kuradal", names.get(0));
		assertEquals(Arrays.asList("Kuradal", "Mazchna", "Vannaka", "Chaeldar", "Konar", "Nieve", "Krystilia"), names);
		assertEquals("duradel", v.getDefaultGroup());
		assertEquals(0, v.getStats().get("konar").getRolls());
		assertTrue(v.getNotices().get("konar").get(0).startsWith("Open Konar's task list"));
	}

	@Test
	public void heldTaskCanBeTickedBeforeItsChanceIsKnown()
	{
		final TrackerData d = new TrackerData();
		d.getSnapshots().add(OddsParsingTest.snapshot(KuradalFixture.ON_FIRE_GIANTS, "Fire Giants"));
		d.getWanted().put("duradel", new ArrayList<>(Arrays.asList("Abyssal Demons", "Kalphite Queen")));

		TrackerView.WantedOption fire = option(view(d), "Fire Giants");
		assertNull("the list shows a held task as 0%", fire.getChance());
		assertFalse(fire.isWanted());
		assertTrue(fire.getNote() != null);
		final TrackerView.WantedOption gone = option(view(d), "Kalphite Queen");
		assertEquals(0.0, gone.getChance(), 0);
		assertTrue("a wanted task off the list can still be unticked", gone.isWanted());

		// An older list opened without a task supplies the weight.
		final OddsSnapshot older = OddsParsingTest.snapshot(KuradalFixture.NO_TASK, null);
		older.setTimestamp(500);
		d.getSnapshots().add(older);
		fire = option(view(d), "Fire Giants");
		assertEquals(KuradalFixture.expectedWeight("Fire Giants") / 161.0, fire.getChance(), 1e-12);
		assertNull(fire.getNote());
	}

	private static TrackerView view(TrackerData d)
	{
		return ViewBuilder.build(d, TrackerView.State.READY, null, null, 0.1, 0.1,
			name -> Masters.isFiller(name, 0, true, true, true), 90, 120, null);
	}

	private static TrackerView.WantedOption option(TrackerView v, String task)
	{
		for (TrackerView.WantedOption o : v.getWantedOptions().get("duradel"))
		{
			if (o.getTask().equals(task))
			{
				return o;
			}
		}
		throw new AssertionError(task + " isn't offered");
	}

	@Test
	public void fairnessRunsOnceThereAreEnoughRolls()
	{
		final TrackerData d = new TrackerData();
		d.getSnapshots().add(OddsParsingTest.snapshot(KuradalFixture.NO_TASK, null));
		d.getWanted().put("duradel", Arrays.asList("Abyssal Demons"));
		final String[] tasks = {"Gargoyles", "Trolls", "Drakes", "Wyrms", "Hellhounds", "Nechryael", "Ankou", "Suqahs", "Elves", "Bloodveld"};
		for (int i = 0; i < 60; i++)
		{
			add(d, 2000 + i * MIN, "Kuradal", tasks[i % tasks.length], false);
		}
		final GroupStats s = StatsCalculator.compute(d, "duradel", "Kuradal", 0.1, 0.1, true);
		assertEquals(60, s.getFairness().getRolls());
		assertTrue(s.getFairness().getPValue() > 0 && s.getFairness().getPValue() <= 1);
		assertEquals(Verdict.Tone.UNLUCKY, s.getDryVerdict().getTone()); // 60 rolls, 0 abyssals at 7.45%
	}
}

package com.slayertaskluck.tracking;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import com.google.gson.Gson;
import com.slayertaskluck.SlayerTaskLuckConfig;
import com.slayertaskluck.model.Roll;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.util.Filepath;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * Replays Slayer varp changes through {@link SlayerTracker} the way the game sends them, and checks which ones are
 * logged as rolls. Task Storage moves a task in or out of {@code SLAYER_STORED_VARP}; a master's assignment doesn't
 * touch it.
 */
public class SlayerTrackerTest
{
	private static final int NECHRYAEL = 52;
	private static final int GARGOYLES = 46;
	private static final int ABYSSAL_DEMONS = 42;
	private static final int BATS = 8;

	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	private final Map<Integer, Integer> varps = new HashMap<>();
	private final Map<Integer, Integer> varbits = new HashMap<>();
	private int tick = 1000;
	private int gap = 3;
	private ScheduledExecutorService executor;
	private TrackerStore store;
	private SlayerTracker tracker;

	@Before
	public void setUp() throws Exception
	{
		final Client client = mock(Client.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getTickCount()).thenAnswer(i -> tick);
		when(client.getVarpValue(anyInt())).thenAnswer(i -> varps.getOrDefault(i.<Integer>getArgument(0), 0));
		when(client.getVarbitValue(anyInt())).thenAnswer(i -> varbits.getOrDefault(i.<Integer>getArgument(0), 0));
		final SlayerTaskLuckConfig config = mock(SlayerTaskLuckConfig.class);
		when(config.fillerAya()).thenReturn(true);
		when(config.fillerTurael()).thenReturn(true);
		when(config.fillerSpria()).thenReturn(true);

		executor = Executors.newSingleThreadScheduledExecutor();
		final Path dir = folder.getRoot().toPath();
		final Filepath root = Filepath.Unchecked.getRooted(dir);
		store = new TrackerStore(new Gson(), executor, () -> root, () -> { });
		store.switchProfile("test");
		executor.submit(() -> { }).get(5, TimeUnit.SECONDS);

		tracker = new SlayerTracker(client, store, config, () -> { });
		tracker.start();
	}

	@After
	public void tearDown()
	{
		executor.shutdownNow();
	}

	@Test
	public void anAssignmentIsLogged()
	{
		assign("Kuradal", 5, GARGOYLES, 150);
		assertEquals(Arrays.asList("Task #46"), logged());
	}

	@Test
	public void storingAndUnstoringAreNotRolls()
	{
		assign("Kuradal", 5, NECHRYAEL, 227);
		store();
		assign("Aya", 1, BATS, 26);
		finishTask();
		unstore();
		assertEquals(Arrays.asList("Task #52", "Task #8"), logged());
	}

	@Test
	public void aSwapIsNotARoll()
	{
		assign("Kuradal", 5, NECHRYAEL, 227);
		store();
		assign("Kuradal", 5, GARGOYLES, 150);
		swap();
		assertEquals(Arrays.asList("Task #52", "Task #46"), logged());
	}

	/** The reported bug: unstore, store again, then right-click Assignment straight away. */
	@Test
	public void anAssignmentRightAfterStoringIsLogged()
	{
		assign("Kuradal", 5, NECHRYAEL, 227);
		store();
		unstore();
		gap = 1; // the new task arrives on the very next tick after storing
		store();
		assign("Kuradal", 5, ABYSSAL_DEMONS, 220);
		assertEquals(Arrays.asList("Task #52", "Task #42"), logged());
	}

	@Test
	public void anAssignmentWithATaskInStorageIsLogged()
	{
		assign("Kuradal", 5, NECHRYAEL, 227);
		store();
		assign("Aya", 1, BATS, 26);
		finishTask();
		assign("Kuradal", 5, GARGOYLES, 150);
		assertEquals(Arrays.asList("Task #52", "Task #8", "Task #46"), logged());
	}

	/** Even with no storage change to go on, a task that comes back with kills already done isn't an assignment. */
	@Test
	public void aTaskWithKillsDoneIsNotARoll()
	{
		assign("Kuradal", 5, NECHRYAEL, 227);
		varps.put(VarPlayerID.SLAYER_COUNT, 180); // kills lower the count without any event the tracker acts on
		set(VarPlayerID.SLAYER_TARGET, 0);
		set(VarPlayerID.SLAYER_COUNT, 0);
		next();
		assign("Aya", 1, BATS, 26);
		finishTask();
		set(VarPlayerID.SLAYER_TARGET, NECHRYAEL);
		set(VarPlayerID.SLAYER_COUNT_ORIGINAL, 227);
		set(VarPlayerID.SLAYER_COUNT, 180);
		next();
		assertEquals(Arrays.asList("Task #52", "Task #8"), logged());
	}

	// ---- the game, as the tracker sees it ----

	private int storedTarget;
	private int storedCount;
	private int storedOriginal;

	private void assign(String master, int slot, int target, int amount)
	{
		final ChatMessage line = new ChatMessage();
		line.setType(ChatMessageType.DIALOG);
		line.setMessage(master + "|Your new task is to kill " + amount + ".");
		tracker.onChatMessage(line);
		varbits.put(VarbitID.SLAYER_MASTER, slot);
		set(VarPlayerID.SLAYER_TARGET, target);
		set(VarPlayerID.SLAYER_COUNT_ORIGINAL, amount);
		set(VarPlayerID.SLAYER_COUNT, amount);
		next();
	}

	private void finishTask()
	{
		set(VarPlayerID.SLAYER_COUNT, 0);
		next();
	}

	/** Rewards > Tasks > Store task: the current task moves into storage. */
	private void store()
	{
		storedTarget = varps.getOrDefault(VarPlayerID.SLAYER_TARGET, 0);
		storedCount = varps.getOrDefault(VarPlayerID.SLAYER_COUNT, 0);
		storedOriginal = varps.getOrDefault(VarPlayerID.SLAYER_COUNT_ORIGINAL, 0);
		set(VarPlayerID.SLAYER_STORED_VARP, storedTarget << 16 | storedCount);
		set(VarPlayerID.SLAYER_COUNT, 0);
		next();
	}

	/** Rewards > Tasks > Unstore: the stored task becomes the current task again. */
	private void unstore()
	{
		set(VarPlayerID.SLAYER_STORED_VARP, 0);
		set(VarPlayerID.SLAYER_TARGET, storedTarget);
		set(VarPlayerID.SLAYER_COUNT_ORIGINAL, storedOriginal);
		set(VarPlayerID.SLAYER_COUNT, storedCount);
		next();
	}

	/** Rewards > Tasks > Swap: the current and stored tasks trade places. */
	private void swap()
	{
		final int target = varps.get(VarPlayerID.SLAYER_TARGET);
		final int count = varps.get(VarPlayerID.SLAYER_COUNT);
		final int original = varps.get(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		set(VarPlayerID.SLAYER_STORED_VARP, target << 16 | count);
		set(VarPlayerID.SLAYER_TARGET, storedTarget);
		set(VarPlayerID.SLAYER_COUNT_ORIGINAL, storedOriginal);
		set(VarPlayerID.SLAYER_COUNT, storedCount);
		storedTarget = target;
		storedCount = count;
		storedOriginal = original;
		next();
	}

	private void set(int varp, int value)
	{
		varps.put(varp, value);
		final VarbitChanged event = new VarbitChanged();
		event.setVarpId(varp);
		event.setVarbitId(-1);
		event.setValue(value);
		tracker.onVarbitChanged(event);
	}

	/** The tracker reads changes back on the next tick; {@link #gap} ticks pass before the next action. */
	private void next()
	{
		for (int i = 0; i < gap; i++)
		{
			tick++;
			tracker.onGameTick(new GameTick());
		}
	}

	private List<String> logged()
	{
		return store.copy().getRolls().stream().map(Roll::getTask).collect(Collectors.toList());
	}
}

package com.slayertaskluck.tracking;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.slayertaskluck.model.TrackerData;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import net.runelite.client.util.Filepath;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class TrackerStoreTest
{
	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	private ScheduledExecutorService executor;
	private Path dir;

	@Before
	public void setUp()
	{
		executor = Executors.newSingleThreadScheduledExecutor();
		dir = folder.getRoot().toPath();
	}

	@After
	public void tearDown()
	{
		executor.shutdownNow();
	}

	private TrackerStore newStore()
	{
		final Filepath root = Filepath.Unchecked.getRooted(dir);
		return new TrackerStore(new Gson(), executor, () -> root, () -> { });
	}

	private void drain() throws Exception
	{
		executor.submit(() -> { }).get(5, TimeUnit.SECONDS);
	}

	@Test
	public void savesAndReloadsAProfile() throws Exception
	{
		final TrackerStore store = newStore();
		store.switchProfile("abc123");
		drain();
		assertTrue(store.isLoaded());

		store.addSnapshot(OddsParsingTest.snapshot(KuradalFixture.NO_TASK, null));
		store.setWanted("duradel", Collections.singletonList("Abyssal Demons"));
		store.recordRoll(RollDraft.builder().timestamp(5000).masterName("Kuradal").masterSlot(5)
			.masterGroup("duradel").task("Abyssal Demons").amount(200).build());
		store.flush();
		drain();
		assertTrue(Files.exists(dir.resolve("abc123.json")));

		final TrackerStore reloaded = newStore();
		reloaded.switchProfile("abc123");
		drain();
		final TrackerData d = reloaded.copy();
		assertEquals(1, d.getRolls().size());
		assertEquals(1, d.getSnapshots().size());
		assertTrue(d.getRolls().get(0).getWanted());
		assertEquals("Kuradal", reloaded.nameForSlot(5));
	}

	@Test
	public void createsTheDataFolderOnFirstSave() throws Exception
	{
		// Like getPluginDirectory(): the returned folder doesn't exist yet.
		final Path missing = dir.resolve("plugin-data").resolve("slayer-task-luck");
		final Filepath root = Filepath.Unchecked.getRooted(missing);
		final TrackerStore store = new TrackerStore(new Gson(), executor, () -> root, () -> { });
		store.switchProfile("fresh");
		drain();
		store.setWanted("duradel", Collections.singletonList("Abyssal Demons"));
		store.flush();
		drain();
		assertTrue(Files.exists(missing.resolve("fresh.json")));
		assertEquals(null, store.getProblem());
	}

	@Test
	public void unreadableFileIsSetAsideNotLost() throws Exception
	{
		Files.write(dir.resolve("broken.json"), "{ not json".getBytes(StandardCharsets.UTF_8));
		final TrackerStore store = newStore();
		store.switchProfile("broken");
		drain();
		assertTrue(store.isLoaded());
		assertNotNull(store.getProblem());
		assertEquals(0, store.copy().getRolls().size());
		assertTrue(Files.list(dir).anyMatch(p -> p.getFileName().toString().startsWith("broken.json.unreadable-")));
	}

	@Test
	public void identicalListIsNotStoredTwice() throws Exception
	{
		final TrackerStore store = newStore();
		store.switchProfile("dedupe");
		drain();
		store.addSnapshot(OddsParsingTest.snapshot(KuradalFixture.NO_TASK, null));
		store.addSnapshot(OddsParsingTest.snapshot(KuradalFixture.NO_TASK, null));
		assertEquals(1, store.copy().getSnapshots().size());
		store.addSnapshot(OddsParsingTest.snapshot(KuradalFixture.ON_FIRE_GIANTS, "Fire Giants"));
		assertEquals(2, store.copy().getSnapshots().size());
	}
}
